-- Enable RLS on all tables
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- Helper function to check if user is a member of a specific team with a specific role
create or replace function public.is_member_of_team(p_team_id bigint, p_role text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.team_members
    where team_id = p_team_id
    and user_id = auth.uid()
    and role = p_role
  );
$$;

-- R1: Users can see the teams they belong to (any role)
create policy "Users can view teams they belong to"
on public.teams
for select
using (
  exists (
    select 1 from public.team_members
    where team_id = public.teams.id
    and user_id = auth.uid()
  )
);

-- R2: Users can see their own membership rows, but not others
create policy "Users can view their own team memberships"
on public.team_members
for select
using (user_id = auth.uid());

-- R3: Members of a team can read team documents (non-deleted)
create policy "Team members can read team documents"
on public.documents
for select
using (
  team_id in (
    select team_id from public.team_members where user_id = auth.uid()
  )
  and deleted_at is null
);

-- R4: Editors can create documents in their teams; Viewers cannot
create policy "Editors can create documents in their teams"
on public.documents
for insert
with check (
  is_member_of_team(team_id, 'editor')
);

-- R5: Editors can edit any document in their teams (only if they are editors)
create policy "Editors can update documents in their teams"
on public.documents
for update
using (
  is_member_of_team(team_id, 'editor')
  and deleted_at is null
);

-- R6: Only the creator can delete a document (soft delete via deleted_at)
create policy "Only creators can soft delete documents"
on public.documents
for update
using (
  created_by = auth.uid()
  and deleted_at is null
);

-- R7: Teams and memberships cannot be created, changed or removed by users
-- Deny insert, update, delete on teams
create policy "Deny user modifications to teams"
on public.teams
for all
using (false);

-- Deny insert, update, delete on team_members
create policy "Deny user modifications to team_members"
on public.team_members
for all
using (false);

-- R8: Anonymous visitors cannot see or change anything
-- (Implicitly handled by 'using (auth.uid() is not null)' in policies above, but explicit deny for clarity on specific actions if needed. 
-- However, standard Supabase practice relies on the 'using' clause failing for anon. 
-- To be explicit and safe against any policy that might not check auth.uid():
create policy "Deny anonymous access to all tables"
on public.teams
for all
using (auth.role() = 'authenticated');
create policy "Deny anonymous access to team_members"
on public.team_members
for all
using (auth.role() = 'authenticated');
create policy "Deny anonymous access to documents"
on public.documents
for all
using (auth.role() = 'authenticated');

-- R9: Service role keeps full access
-- (Implicitly handled by Supabase default behavior for service_role, but we can ensure no policies block it if we used 'with check' or 'using' that might fail. 
-- Since our policies use 'using' or 'with check' that evaluate auth.uid(), service_role bypasses RLS entirely, so no extra policy is strictly needed. 
-- However, to be explicit about the intent:
revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;
revoke all on public.teams from authenticated; -- Service role bypasses, but we want to ensure anon/authenticated don't have direct grants that bypass RLS logic if any
revoke all on public.team_members from authenticated;
revoke all on public.documents from authenticated;

-- Grant necessary permissions for the helper function to be usable in policies
grant execute on function public.is_member_of_team(bigint, text) to authenticated;

-- Ensure service_role has full access (default, but explicit for clarity)
grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;
