create policy "Team members can read team documents"
on public.documents
for select
using (
  team_id in (
    select team_id from public.team_members
    where user_id = auth.uid()
    and role in ('viewer', 'editor')
  )
  and deleted_at is null
);

-- R4: Editors can create documents in their teams. Viewers cannot.
create policy "Editors can create documents in their teams"
on public.documents
for insert
with check (
  is_team_editor(team_id, auth.uid())
);

-- R5: Editors can edit any document in their teams.
-- Condition: User must be an editor in the team of the document being updated.
create policy "Editors can update documents in their teams"
