revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;
-- Ensure authenticated users can't do admin things if not covered, but our specific policies cover the scope.

-- Grant necessary permissions to authenticated users to run these policies if they don't exist
-- (Standard Supabase setup grants usage on auth, but let's ensure table permissions are correct for the app user)
grant all on public.teams to authenticated;
grant all on public.team_members to authenticated;
grant all on public.documents to authenticated;
