-- Enable RLS on all tables
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.projects enable row level security;

-- Helper function to check if user is an admin of an org
create or replace function public.is_org_admin(org_id bigint, user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.org_members
    where org_members.org_id = org_id
    and org_members.user_id = user_id
    and org_members.role = 'admin'
  );
$$;

-- Helper function to check if user is a member of an org
create or replace function public.is_org_member(org_id bigint, user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.org_members
    where org_members.org_id = org_id
    and org_members.user_id = user_id
  );
$$;

-- R1: Members can see every membership row of their org; nothing else.
create policy "org_members_select_own_org" on public.org_members
  for select
  using (
    auth.uid() is not null
    and exists (
      select 1 from public.org_members m
      where m.org_id = org_members.org_id
      and m.user_id = auth.uid()
    )
  );

-- R2: Members can see orgs they belong to and those orgs' projects.
create policy "orgs_select_own_orgs" on public.orgs
  for select
  using (
    auth.uid() is not null
    and exists (
      select 1 from public.org_members m
      where m.org_id = orgs.id
      and m.user_id = auth.uid()
    )
  );

create policy "projects_select_own_orgs" on public.projects
  for select
  using (
    auth.uid() is not null
    and exists (
      select 1 from public.org_members m
      where m.org_id = projects.org_id
      and m.user_id = auth.uid()
    )
  );

-- R3: Only admins can create, rename (update), or delete projects within their orgs.
create policy "projects_insert_admin" on public.projects
  for insert
  with check (
    auth.uid() is not null
    and public.is_org_admin(projects.org_id, auth.uid())
  );

create policy "projects_update_admin" on public.projects
  for update
  using (
    auth.uid() is not null
    and public.is_org_admin(projects.org_id, auth.uid())
  );

create policy "projects_delete_admin" on public.projects
  for delete
  using (
    auth.uid() is not null
    and public.is_org_admin(projects.org_id, auth.uid())
  );

-- R6: Memberships cannot be created, changed, or removed by users of the app.
create policy "org_members_no_user_modifications" on public.org_members
  for all
  using ( false );

-- R7: Anonymous visitors cannot see or change anything else (orgs, projects, org_members).
-- Explicitly deny insert/update/delete on orgs and projects for anon.
create policy "orgs_no_anon_write" on public.orgs
  for all
  to anon
  using ( false );

create policy "projects_no_anon_write" on public.projects
  for all
  to anon
  using ( false );

-- R8: Service role keeps full access (default behavior, but explicit grant for clarity if needed).
-- RLS bypasses for service_role by default, but we ensure no restrictions apply.
grant all on all tables in schema public to service_role;

-- Storage Policies for R4 and R5
-- R4: Members can read project files. Only admins can upload/delete project files.
-- Bucket: project-files
create policy "project_files_select" on storage.objects
  for select
  on bucket = 'project-files'
  using (
    auth.uid() is not null
    and exists (
      select 1 from public.org_members m
      where m.org_id = (
        select id from public.projects p
        where p.id = split_part(path, '/', 1)::bigint
      )
      and m.user_id = auth.uid()
    )
  );

create policy "project_files_insert_admin" on storage.objects
  for insert
  on bucket = 'project-files'
  with check (
    auth.uid() is not null
    and public.is_org_admin(
      (select id from public.projects p where p.id = split_part(path, '/', 1)::bigint),
      auth.uid()
    )
  );

create policy "project_files_update_admin" on storage.objects
  for update
  on bucket = 'project-files'
  using (
    auth.uid() is not null
    and public.is_org_admin(
      (select id from public.projects p where p.id = split_part(path, '/', 1)::bigint),
      auth.uid()
    )
  );

create policy "project_files_delete_admin" on storage.objects
  for delete
  on bucket = 'project-files'
  using (
    auth.uid() is not null
    and public.is_org_admin(
      (select id from public.projects p where p.id = split_part(path, '/', 1)::bigint),
      auth.uid()
    )
  );

-- R5: Anyone can view avatars. Signed-in users can upload avatars only into their own folder.
-- Bucket: avatars
create policy "avatars_select_public" on storage.objects
  for select
  on bucket = 'avatars'
  to anon, authenticated
  using ( true );

create policy "avatars_insert_own" on storage.objects
  for insert
  on bucket = 'avatars'
  to authenticated
  with check (
    auth.uid() is not null
    and path begins with auth.uid()::text || '/'
  );

create policy "avatars_update_own" on storage.objects
  for update
  on bucket = 'avatars'
  to authenticated
  using (
    auth.uid() is not null
    and path begins with auth.uid()::text || '/'
  );

create policy "avatars_delete_own" on storage.objects
  for delete
  on bucket = 'avatars'
  to authenticated
  using (
    auth.uid() is not null
    and path begins with auth.uid()::text || '/'
  );
