-- Enable RLS on all tables
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.projects enable row level security;

-- Helper function to check if current user is an admin of a specific org
create or replace function public.is_org_admin(org_id bigint) returns boolean language sql stable as $$
  select exists (
    select 1 from public.org_members 
    where org_members.org_id = orgs.id 
    and org_members.role = 'admin'
    and org_members.user_id = auth.uid()
  )
$$;

-- Helper function to check if current user is a member (admin or member) of a specific org
create or replace function public.is_org_member(org_id bigint) returns boolean language sql stable as $$
  select exists (
    select 1 from public.org_members 
    where org_members.org_id = orgs.id 
    and org_members.user_id = auth.uid()
  )
$$;

-- RLS: orgs table
create policy "Org members can view their organization" on public.orgs
  for select using (public.is_org_member(id));

create policy "Service role can manage orgs" on public.orgs
  for all using (true) with check (true);

-- RLS: org_members table
-- R1: Members see only rows for orgs they belong to
create policy "Org members can view their org membership" on public.org_members
  for select using (org_id in (select id from public.orgs where public.is_org_member(id)));

-- R6: No insert, update, delete for app users
create policy "Block org_membership modifications" on public.org_members
  for all using (false);

-- Service role full access
create policy "Service role can manage org_members" on public.org_members
  for all using (true) with check (true);

-- RLS: projects table
-- R2: Members can see projects of orgs they belong to
create policy "Org members can view their org projects" on public.projects
  for select using (org_id in (select id from public.orgs where public.is_org_member(id)));

-- R3: Only admins can insert, update, delete projects within their orgs
create policy "Org admins can manage projects" on public.projects
  for all using (public.is_org_admin(org_id)) with check (public.is_org_admin(org_id));

-- Service role full access
create policy "Service role can manage projects" on public.projects
  for all using (true) with check (true);

-- RLS: storage buckets and objects
-- Note: RLS on storage is typically applied to the storage.objects table via policies on the bucket, 
-- but Supabase recommends using Storage Policies in the UI or SQL equivalent on storage.objects.
-- However, standard SQL RLS on storage.objects exists. We will apply it there.
alter table storage.objects enable row level security;

-- R4: Members can read project files. Only admins can upload/delete.
-- Path format: <project_id>/<file_name>
-- We need to resolve project_id from the path prefix.
-- Left path segments: path.split('/').slice(0, -1).join('/') -> project_id
-- Right path segments: path.split('/').slice(-1)[0] -> file_name

create policy "Org members can read project files" on storage.objects
  for select using (
    bucket_id = 'project-files' 
    and (
      -- Check if the user is a member of the org owning the project
      exists (
        select 1 from public.org_members om
        join public.orgs o on o.id = om.org_id
        where om.user_id = auth.uid()
        and o.id = (
          -- Extract project ID from path: project_id/file_name
          -- If path is '123/file.txt', left is '123'
          (substring(path from '^([0-9]+)/.*')::bigint)
        )
      )
    );
  );

create policy "Org admins can upload project files" on storage.objects
  for insert with check (
    bucket_id = 'project-files'
    and exists (
      select 1 from public.org_members om
      join public.orgs o on o.id = om.org_id
      where om.user_id = auth.uid()
      and om.role = 'admin'
      and o.id = (
        (substring(path from '^([0-9]+)/.*')::bigint)
      )
    );
  );

create policy "Org admins can delete project files" on storage.objects
  for delete using (
    bucket_id = 'project-files'
    and exists (
      select 1 from public.org_members om
      join public.orgs o on o.id = om.org_id
      where om.user_id = auth.uid()
      and om.role = 'admin'
      and o.id = (
        (substring(path from '^([0-9]+)/.*')::bigint)
      )
    );
  );

-- Service role full access for storage
create policy "Service role can manage storage.objects" on storage.objects
  for all using (true) with check (true);

-- RLS: avatars bucket and objects
alter table storage.objects enable row level security;

-- R5: Anyone can view avatars. Signed-in users upload only to their own folder.
-- Path format: <user_id>/<file_name>

create policy "Public read avatars" on storage.objects
  for select using (bucket_id = 'avatars' or true);

create policy "Users upload own avatars" on storage.objects
  for insert with check (
    bucket_id = 'avatars'
    and auth.uid() = (
      -- Extract user_id from path: user_id/file_name
      (substring(path from '^([a-f0-9-]+)/.*')::uuid)
    );
  );

create policy "Users delete own avatars" on storage.objects
  for delete using (
    bucket_id = 'avatars'
    and auth.uid() = (
      (substring(path from '^([a-f0-9-]+)/.*')::uuid)
    );
  );

-- Service role full access for storage
create policy "Service role can manage storage.objects" on storage.objects
  for all using (true) with check (true);

-- Grants for service_role to ensure it bypasses RLS if needed (though policies with service_role check usually handle it)
-- Explicitly grant all on tables/views for service_role if not covered by policy 'using (true)'
grant all on all tables in schema public to service_role;
grant all on all tables in schema storage to service_role;
grant usage on all sequences in schema public to service_role;
grant usage on all sequences in schema storage to service_role;
