-- Create helper function for decision logic
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean) returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Check if expense is pending
  if not exists (select 1 from public.expenses where id = p_expense_id and status = 'pending') then
    raise exception 'Expense is not pending';
  end if;

  -- Get the expense details to check department and submitter
  declare
    v_department_id bigint;
    v_submitter_id uuid;
  begin
    select department_id, submitted_by into v_department_id, v_submitter_id
    from public.expenses
    where id = p_expense_id;

    -- Check if caller is a manager of the expense's department
    if not exists (
      select 1
      from public.department_members dm
      join auth.users u on u.id = dm.user_id
      where dm.department_id = v_department_id
        and u.raw_user_meta_data->>'sub' = current_setting('request.jwt.claims', true)->>'sub'
        and dm.is_manager = true
    ) then
      raise exception 'Caller is not a manager of the department';
    end if;

    -- Check if caller is the submitter (should not be)
    if v_submitter_id = current_setting('request.jwt.claims', true)->>'sub'::uuid then
      raise exception 'Manager cannot decide on their own submission';
    end if;

    -- Update the expense
    update public.expenses
    set status = case when p_approve then 'approved' else 'rejected' end,
        decided_by = current_setting('request.jwt.claims', true)->>'sub'::uuid
    where id = p_expense_id;
  end;
end;
$$;

