on public.expenses for all
using ( auth.role() = 'service_role' );
create policy "Service role has full access to departments"
on public.departments for all
using ( auth.role() = 'service_role' );
create policy "Service role has full access to department_members"
on public.department_members for all
using ( auth.role() = 'service_role' );

-- Policy R1: Users can read their own expenses
