-- Enable RLS on all tables
alter table public.courses enable row level security;
alter table public.lessons enable row level security;
alter table public.enrollments enable row level security;

-- Helper function to check if a user is an instructor of a course
create or replace function public.is_course_instructor(course_id bigint, user_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from public.courses 
    where id = course_id and instructor_id = user_id
  );
$$;

-- Helper function to check if a user is enrolled in a course
create or replace function public.is_enrolled(course_id bigint, user_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from public.enrollments 
    where course_id = course_id and student_id = user_id
  );
$$;

-- Helper function to check if a course is published
create or replace function public.is_course_published(course_id bigint)
returns boolean
language sql
stable
as $$
  select is_published from public.courses where id = course_id;
$$;

-- Helper function to check if a lesson is a preview
create or replace function public.is_lesson_preview(lesson_id bigint)
returns boolean
language sql
stable
as $$
  select is_preview from public.lessons where id = lesson_id;
$$;

-- Helper function to check if a course is published OR the user is the instructor
create or replace function public.can_access_course(course_id bigint, user_id uuid)
returns boolean
language sql
stable
as $$
  select 
    (select is_published from public.courses where id = course_id) 
    or public.is_course_instructor(course_id, user_id);
$$;

-- Helper function to check if a user can read a lesson
create or replace function public.can_read_lesson(lesson_id bigint, user_id uuid)
returns boolean
language sql
stable
as $$
  declare
    course_id bigint;
    is_preview boolean;
    is_published boolean;
    is_instructor boolean;
    is_enrolled boolean;
  begin
    select course_id, is_preview into course_id, is_preview from public.lessons where id = lesson_id;
    select is_published into is_published from public.courses where id = course_id;
    select public.is_course_instructor(course_id, user_id) into is_instructor;
    select public.is_enrolled(course_id, user_id) into is_enrolled;

    -- Anyone can read preview lessons of published courses
    if is_preview and is_published then
      return true;
    end if;

    -- Students enrolled in a published course can read all lessons
    if is_enrolled and is_published then
      return true;
    end if;

    -- Instructors can read all lessons of their own courses
    if is_instructor then
      return true;
    end if;

    return false;
  end;
$$;

-- Helper function to check if a user can enroll in a course
create or replace function public.can_enroll(course_id bigint, user_id uuid)
returns boolean
language sql
stable
as $$
  select 
    (select is_published from public.courses where id = course_id) 
    and not public.is_enrolled(course_id, user_id);
$$;

-- Courses: Select
create policy "Anyone can read published courses"
on public.courses for select
using (public.is_course_published(id));

create policy "Instructors can read their own unpublished courses"
on public.courses for select
using (public.is_course_instructor(id, auth.uid()));

-- Courses: Insert
create policy "Signed-in users can create courses as their instructor"
on public.courses for insert
with check (auth.uid() = instructor_id);

-- Courses: Update
create policy "Instructors can edit their own courses"
on public.courses for update
using (public.is_course_instructor(id, auth.uid()));

-- Courses: Delete
create policy "Instructors can delete their own courses"
on public.courses for delete
using (public.is_course_instructor(id, auth.uid()));

-- Lessons: Select
create policy "Anyone can read preview lessons of published courses"
on public.lessons for select
using (public.is_lesson_preview(id) and public.is_course_published(course_id));

create policy "Students enrolled in published courses can read all lessons"
on public.lessons for select
using (public.is_enrolled(course_id, auth.uid()) and public.is_course_published(course_id));

create policy "Instructors can read all lessons of their own courses"
on public.lessons for select
using (public.is_course_instructor(course_id, auth.uid()));

-- Lessons: Insert
create policy "Instructors can create lessons for their own courses"
on public.lessons for insert
with check (public.is_course_instructor(course_id, auth.uid()));

-- Lessons: Update
create policy "Instructors can edit lessons of their own courses"
on public.lessons for update
using (public.is_course_instructor(course_id, auth.uid()));

-- Lessons: Delete
create policy "Instructors can delete lessons of their own courses"
on public.lessons for delete
using (public.is_course_instructor(course_id, auth.uid()));

-- Enrollments: Insert
create policy "Signed-in users can enroll themselves in published courses"
on public.enrollments for insert
with check (auth.uid() = student_id and public.can_enroll(course_id, auth.uid()));

-- Enrollments: Update
create policy "Users can update their own enrollments"
on public.enrollments for update
using (auth.uid() = student_id);

-- Enrollments: Delete
create policy "Users can delete their own enrollments"
on public.enrollments for delete
using (auth.uid() = student_id);

-- Enrollments: Select
create policy "Students can see their own enrollments"
on public.enrollments for select
using (auth.uid() = student_id);

create policy "Instructors can see enrollments in their courses"
on public.enrollments for select
using (public.is_course_instructor(course_id, auth.uid()));

-- Grant service_role full access to bypass RLS for server-side code
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;
grant all on all sequences in schema public to service_role;
```

