-- Enable RLS on all tables
alter table public.patients enable row level security;
alter table public.care_team enable row level security;
alter table public.records enable row level security;

-- Function to check if user is a doctor with MFA (aal2)
create or replace function public.is_doctor_with_mfa()
returns boolean
language sql
security invoker
stable
as $$
  select (
    auth.jwt()->>'role' = 'authenticated' 
    and auth.jwt()->>'aal' = 'aal2'
  );
$$;

-- Function to check if current user is a doctor in the care team for a specific patient
create or replace function public.doctor_in_care_team(patient_id bigint)
returns boolean
language sql
security invoker
stable
as $$
  select exists (
    select 1 from public.care_team 
    where care_team.patient_id = patient_id 
    and care_team.doctor_id = auth.uid()
  );
$$;

-- Function to check if current user is the patient owner
create or replace function public.is_patient_owner()
returns boolean
language sql
security invoker
stable
as $$
  select exists (
    select 1 from public.patients 
    where patients.user_id = auth.uid()
  );
$$;

-- Function to check if current user is involved in the care team (either as patient or doctor)
create or replace function public.user_in_care_team()
returns boolean
language sql
security invoker
stable
as $$
  select exists (
    select 1 from public.patients p
    join public.care_team ct on ct.patient_id = p.id
    where p.user_id = auth.uid()
    or ct.doctor_id = auth.uid()
  );
$$;

-- ==========================================
-- TABLE: patients
-- ==========================================

-- R7: Anonymous users cannot see anything
create policy "Deny anonymous users on patients" on public.patients
for select using (false);

-- R1: Patients can read their own patient row
create policy "Patients read own row" on public.patients
for select using (auth.uid() = user_id);

-- R2: Doctors with MFA can read patient rows of patients in their care team
create policy "Doctors with MFA read patients in care team" on public.patients
for select 
using (
  public.is_doctor_with_mfa() 
  and public.doctor_in_care_team(id)
);

-- R8: Service role has full access
create policy "Service role full access" on public.patients
for all using (true) with check (true);

-- ==========================================
-- TABLE: care_team
-- ==========================================

-- R7: Anonymous users cannot see anything
create policy "Deny anonymous users on care_team" on public.care_team
for select using (false);

-- R5: Users can see care-team rows involving them (as patient or doctor)
create policy "Users read care team rows involving them" on public.care_team
for select 
using (
  -- Check if user is the patient
  exists (select 1 from public.patients p where p.id = patient_id and p.user_id = auth.uid())
  -- OR check if user is the doctor
  or exists (select 1 from public.care_team ct where ct.patient_id = patient_id and ct.doctor_id = auth.uid())
);

-- R5: Nobody can change care teams (via insert, update, delete)
create policy "Deny modifications to care_team" on public.care_team
for all using (false);

-- R8: Service role has full access
create policy "Service role full access" on public.care_team
for all using (true) with check (true);

-- ==========================================
-- TABLE: records
-- ==========================================

-- R7: Anonymous users cannot see anything
create policy "Deny anonymous users on records" on public.records
for select using (false);

-- R1: Patients can read their own records
create policy "Patients read own records" on public.records
for select using (patient_id = (select id from public.patients where user_id = auth.uid()));

-- R2: Doctors with MFA can read records of patients in their care team
create policy "Doctors with MFA read records in care team" on public.records
for select 
using (
  public.is_doctor_with_mfa() 
  and patient_id = (select id from public.care_team where doctor_id = auth.uid() limit 1)
);

-- R3: Doctors with MFA can add records for patients in their care team
create policy "Doctors with MFA insert records for care team patients" on public.records
for insert 
using (
  public.is_doctor_with_mfa()
  and patient_id = (select id from public.care_team where doctor_id = auth.uid() limit 1)
);

-- R3: Patients cannot add records (explicit deny for insert, though select policy above covers it, 
-- we need to ensure they can't insert even if they match patient_id logic incorrectly, 
-- but since we only have 'insert' policy for doctors, this is implicitly denied for others unless we add a general deny)
-- However, to be explicit and ensure no other role inserts:
create policy "Deny patient inserts on records" on public.records
for insert using (false);

-- R4: Records can never be changed (update) or deleted (delete)
create policy "Deny updates on records" on public.records
for update using (false);
create policy "Deny deletes on records" on public.records
for delete using (false);

-- R8: Service role has full access
create policy "Service role full access" on public.records
for all using (true) with check (true);

-- Grant service_role bypass (supabase handles this automatically via the 'service_role' role often, 
-- but explicitly granting usage on the schema if needed for custom functions called within policies 
-- is good practice if the service role isn't automatically inheriting usage)
grant usage on schema public to service_role;
grant all on function public.is_doctor_with_mfa() to service_role;
grant all on function public.doctor_in_care_team to service_role;
grant all on function public.is_patient_owner to service_role;
grant all on function public.user_in_care_team to service_role;
