-- (Covered by the policies above which restrict to sender_id, and the 'with check' constraint)
-- Also, 'move' (changing conversation_id) is prevented because the 'using' clause checks sender_id against the existing row's sender_id,
-- but more importantly, the 'with check' ensures the update results in a row where sender_id still equals auth.uid().
-- However, to strictly prevent changing conversation_id to one the user isn't in, we rely on the fact that
-- the update operation doesn't inherently validate the target conversation membership unless we add a constraint.
-- The prompt says "Nobody can ... move a message to another conversation".
-- The current policy only checks if the user is updating their own message. It does not check if the new conversation_id is valid for them.
-- We need to add a check to the update policy to ensure the target conversation is valid for the user.

create policy "Users cannot move messages to invalid conversations" on public.messages
for update using (
  auth.uid() = messages.sender_id
  and (
    -- If conversation_id is unchanged, it's already valid (from existing row)
    messages.conversation_id = old.conversation_id
    -- If conversation_id is changed, the user must be in the new conversation
    or exists (
      select 1 from public.participants
      where participants.conversation_id = messages.conversation_id
      and participants.user_id = auth.uid()
    )
  )
  -- And they must not be blocked in the target conversation
  and not public.is_user_blocked_in_conversation(auth.uid(), messages.conversation_id);

-- R5: Users can create the blocks they made
create policy "Users can insert blocks they made" on public.blocks
for insert with check (
  auth.uid() = blocks.blocker_id
);

-- R5: Users can see the blocks they made
create policy "Users can view blocks they made" on public.blocks
for select using (
  auth.uid() = blocks.blocker_id
);

-- R5: Users can remove the blocks they made
create policy "Users can delete blocks they made" on public.blocks
for delete using (
  auth.uid() = blocks.blocker_id
);

-- R5: Nobody can see who has blocked them (blocked_id in blocks is private)
-- This is enforced by the SELECT policy above which only allows viewing where blocker_id = auth.uid().
-- Since 'blocked_id' is not exposed unless we explicitly select it, and the policy filters rows,
-- users cannot see rows where they are the blocked_id.

-- R5: Nobody can create blocks for others (covered by insert policy requiring auth.uid() = blocker_id)
-- R5: Nobody can delete blocks made by others (covered by delete policy requiring auth.uid() = blocker_id)

-- R8: Server-side code using the service_role keeps full access
-- We need to grant all privileges to the service_role on all tables.
-- Note: 'service_role' is a predefined role in Supabase that bypasses RLS.
-- The policies above use 'auth.role() = 'authenticated'' which excludes service_role usually unless specified.
-- However, 'service_role' bypasses RLS entirely on the connection level in Supabase engine,
-- but standard best practice is to grant explicit permissions if RLS is expected to be bypassed by the role.
-- Actually, Supabase's service_role role bypasses RLS by definition.
-- So no additional policy is strictly needed for RLS to work for service_role,
-- but we should ensure they have the necessary permissions if we were using a different mechanism.
-- Since 'service_role' bypasses RLS, the grants below are technically redundant for RLS enforcement
-- but good for completeness if the role were different.
-- Wait, the requirement says "Server-side code using the service role keeps full access".
-- This is automatically handled by the 'service_role' role in Supabase which bypasses RLS.
-- No explicit policy is needed for 'service_role' to work.
-- However, to be safe and explicit about the intent, we can grant all privileges.
-- BUT, the prompt says "Do not modify existing tables or data". Granting is modifying permissions, not data.
-- And it asks for grants/revokes.

grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;
grant all on all sequences in schema public to service_role;
