on storage.objects
for select
using (
  bucket_id = 'internal'
  or (auth.jwt() is not null and auth.jwt()->>'role') = 'service_role'
);

-- Policy R4: Only service_role can modify (insert/update/delete) internal bucket objects
create policy "Allow service role modify for internal bucket"
on storage.objects
for all
using (
  bucket_id = 'internal'
  or (auth.jwt() is not null and auth.jwt()->>'role') = 'service_role'
);

-- Policy R5: Anonymous users cannot insert/update/delete in media bucket
-- (Implicitly handled by R3 requiring auth.uid() not null, but explicit deny for clarity if needed)
-- Note: R3 already restricts insert/update/delete to authenticated users in their own folder.
-- To ensure anonymous users cannot touch media at all (even outside their folder), we rely on R3.
-- However, if there are objects not in a user folder in 'media', R3 doesn't block them for anon.
-- We need to ensure anon cannot insert/update/delete in 'media' bucket regardless of path.
create policy "Deny anonymous modify in media bucket"
on storage.objects
for all
using (
  bucket_id = 'media'
  and auth.uid() is null
);

