-- Enable RLS on tables
alter table public.wallets enable row level security;
alter table public.transfers enable row level security;

-- Helper function to check if user is authenticated
create or replace function public.is_authenticated()
returns boolean
language sql
security definer
set search_path = public
as $$
  select case when auth.jwt() is not null then true else false end;
$$;

-- Policy R1: Users can read only their own wallet
create policy "Users can view own wallet"
on public.wallets
for select
using ( auth.uid() = user_id );

-- Policy R2: Users can read transfers they sent or received
create policy "Users can view own transfers"
on public.transfers
for select
using ( from_user = auth.uid() or to_user = auth.uid() );

-- Policy R3: Nobody can create, update, or delete wallets/transfers directly
create policy "Prevent direct wallet modifications"
on public.wallets
for all
using ( false );

create policy "Prevent direct transfer modifications"
on public.transfers
for all
using ( false );

-- Policy R5: Service role has full access
create policy "Service role full access"
on public.wallets
for all
using ( auth.jwt() is null );

create policy "Service role full access"
on public.transfers
for all
using ( auth.jwt() is null );

-- RPC function to send points
create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Check if user is authenticated
  if not public.is_authenticated() then
    raise exception 'User must be signed in to send points';
  end if;

  -- Check if amount is positive
  if p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  -- Get current user
  declare
    v_from_user uuid := auth.uid();
    v_current_balance integer;
    v_new_balance integer;
  begin
    -- Check if caller has enough points
    select balance into v_current_balance
    from public.wallets
    where user_id = v_from_user;

    if v_current_balance < p_amount then
      raise exception 'Insufficient balance';
    end if;

    -- Check if recipient exists
    if not exists (select 1 from public.wallets where user_id = p_to) then
      raise exception 'Recipient does not have a wallet';
    end if;

    -- Check if recipient is the caller
    if p_to = v_from_user then
      raise exception 'Cannot send points to yourself';
    end if;

    -- Perform the transfer logic
    update public.wallets
    set balance = balance - p_amount
    where user_id = v_from_user
    returning balance into v_current_balance;

    update public.wallets
    set balance = balance + p_amount
    where user_id = p_to;

    -- Insert the transfer record
    insert into public.transfers (from_user, to_user, amount)
    values (v_from_user, p_to, p_amount)
    returning id;
  end;
end;
$$;

-- Grant execute on the RPC function to authenticated users
grant execute on function public.send_points(uuid, integer) to authenticated;
