  on public.transfers
  for select
  using (from_user = auth.uid() or to_user = auth.uid());

-- Policy R3: Nobody can create, update, or delete wallets/transfers directly (except service_role which bypasses RLS)
-- We create deny policies for anon and authenticated users for INSERT, UPDATE, DELETE on both tables.
-- Since service_role bypasses RLS, it retains full access.

-- Wallets: Deny direct writes for non-service roles
create policy "Deny direct wallet modifications for users"
  on public.wallets
  for all
  to anon, authenticated
  using (false);

-- Transfers: Deny direct writes for non-service roles
create policy "Deny direct transfer modifications for users"
  on public.transfers
  for all
  to anon, authenticated
  using (false);

-- Function to handle business logic for send_points RPC
create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint language plpgsql security definer set search_path = public as $$
begin
  -- Check if caller is signed in
  if auth.jwt().user_id is null then
    raise exception 'User must be signed in to send points';
  end if;

  -- Check amount is positive
  if p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  -- Check recipient is not the caller
  if p_to = auth.jwt().user_id then
    raise exception 'Cannot send points to yourself';
  end if;

