-- Enable RLS on all tables
alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

-- Helper function to check if a user is a board member with specific role
create or replace function public.is_board_member(p_board_id bigint, p_user_id uuid, p_role text)
returns boolean
language sql stable
as $$
  select exists (
    select 1 from public.board_members
    where board_id = p_board_id
    and user_id = p_user_id
    and role = p_role
  );
$$;

-- Policy R1: Members can see the boards they belong to
create policy "members_can_see_their_boards" on public.boards
for select
using (
  exists (
    select 1 from public.board_members
    where board_members.board_id = public.boards.id
    and board_members.user_id = auth.uid()
  )
);

-- Policy R1: Members can see every member of their boards (viewers and editors)
create policy "members_can_see_board_members" on public.board_members
for select
using (
  public.board_members.board_id = public.boards.id
  and exists (
    select 1 from public.board_members as bm
    where bm.board_id = public.board_members.board_id
    and bm.user_id = auth.uid()
  )
);

-- Policy R2: Members can read all cards on their boards
create policy "members_can_read_cards_on_their_boards" on public.cards
for select
using (
  cards.board_id = boards.id
  and exists (
    select 1 from public.board_members
    where board_members.board_id = cards.board_id
    and board_members.user_id = auth.uid()
  )
);

-- Policy R3 & R4 & R5: Insert cards (Editors only, on active boards)
create policy "editors_can_create_cards" on public.cards
for insert
with check (
  cards.board_id = boards.id
  and board_members.role = 'editor'
  and board_members.user_id = auth.uid()
  and boards.is_archived = false
);

-- Policy R3: Update cards (Editors only, on active boards, must own the board for the update)
create policy "editors_can_update_cards" on public.cards
for update
using (
  cards.board_id = boards.id
  and board_members.role = 'editor'
  and board_members.user_id = auth.uid()
  and boards.is_archived = false
);

-- Policy R3: Delete cards (Editors only, on active boards)
create policy "editors_can_delete_cards" on public.cards
for delete
using (
  cards.board_id = boards.id
  and board_members.role = 'editor'
  and board_members.user_id = auth.uid()
  and boards.is_archived = false
);

-- Policy R6: Boards and memberships cannot be changed through the app (Deny insert/update/delete for anon/authenticated)
create policy "prevent_board_modifications" on public.boards
for all
using ( true ); -- Effectively blocks all operations for non-service roles

create policy "prevent_board_member_modifications" on public.board_members
for all
using ( true ); -- Effectively blocks all operations for non-service roles

-- Policy R7: Anonymous visitors cannot see or change anything
-- (Handled by 'for select' using exists checks for boards/cards, and no allow-all policies for anon)

-- Policy R8: Service role keeps full access
revoke all on public.boards from authenticated, anon;
revoke all on public.board_members from authenticated, anon;
revoke all on public.cards from authenticated, anon;
-- Grants are implicitly given to service_role when RLS is enabled and no specific policies restrict it,
-- but explicit grants ensure service_role has full control if needed by specific policies (though RLS usually bypasses for service_role).
-- To be explicit for service_role bypassing RLS as per standard Supabase behavior:
grant all on public.boards to service_role;
grant all on public.board_members to service_role;
grant all on public.cards to service_role;
