-- Enable RLS on all tables
alter table public.events enable row level security;
alter table public.invites enable row level security;
alter table public.rsvps enable row level security;

-- Helper function to check if a user is the host of an event
create or replace function public.is_host(event_id bigint, user_id uuid)
returns boolean as $$
  select exists (select 1 from public.events where id = event_id and host_id = user_id);
$$ language sql stable;

-- Helper function to check if a user is invited to an event
create or replace function public.is_invited(event_id bigint, user_id uuid)
returns boolean as $$
  select exists (select 1 from public.invites where event_id = event_id and user_id = user_id);
$$ language sql stable;

-- Helper function to check if a user has RSVPed to an event
create or replace function public.has_rsvp(event_id bigint, user_id uuid)
returns boolean as $$
  select exists (select 1 from public.rsvps where event_id = event_id and user_id = user_id);
$$ language sql stable;

-- Helper function to check if an event is full
create or replace function public.is_event_full(event_id bigint)
returns boolean as $$
  select count(*) >= capacity from public.events where id = event_id;
$$ language sql stable;

-- Helper function to check if a user can see an event
create or replace function public.can_see_event(event_id bigint, user_id uuid)
returns boolean as $$
  select 
    e.is_private = false 
    or e.host_id = user_id 
    or exists (select 1 from public.invites where event_id = event_id and user_id = user_id)
  from public.events e
  where e.id = event_id;
$$ language sql stable;

-- Policy R1: Select events
create policy "Users can see public events, hosts and invited users can see private events"
  on public.events for select
  using (
    auth.role() = 'service_role'
    or (
      auth.jwt()->>'role' = 'service_role'
      or (
        auth.uid() is not null
        and (
          (select is_private from public.events where id = id) = false
          or (select host_id from public.events where id = id) = auth.uid()
          or (select exists (select 1 from public.invites where event_id = id and user_id = auth.uid()))
        )
      )
    )
  );

-- Policy R2: Insert events (only host can create)
create policy "Users can create events as their host"
  on public.events for insert
  with check (auth.uid() = host_id);

-- Policy R2: Update events (only host can edit)
create policy "Hosts can edit their own events"
  on public.events for update
  using (auth.uid() = host_id);

-- Policy R2: Delete events (only host can delete)
create policy "Hosts can delete their own events"
  on public.events for delete
  using (auth.uid() = host_id);

-- Policy R3: Insert invites (only host can invite)
create policy "Hosts can invite people to their events"
  on public.invites for insert
  with check (
    exists (select 1 from public.events where id = event_id and host_id = auth.uid())
  );

-- Policy R3: Delete invites (only host can remove invitations)
create policy "Hosts can remove invitations"
  on public.invites for delete
  using (
    exists (select 1 from public.events where id = event_id and host_id = auth.uid())
  );

-- Policy R3: Select invites (users see their own, hosts see all for their events)
create policy "Users can see their own invitations and hosts can see invitations to their events"
  on public.invites for select
  using (
    auth.role() = 'service_role'
    or (
      auth.uid() is not null
      and (
        user_id = auth.uid()
        or exists (select 1 from public.events where id = event_id and host_id = auth.uid())
      )
    )
  );

-- Policy R4: Insert RSVPs (users can RSVP to events they can see, if not full)
create policy "Users can RSVP to events they can see if not full"
  on public.rsvps for insert
  with check (
    auth.role() = 'service_role'
    or (
      auth.uid() is not null
      and can_see_event(event_id, auth.uid())
      and not is_event_full(event_id)
    )
  );

-- Policy R4: Delete RSVPs (users can cancel their own RSVPs)
create policy "Users can cancel their own RSVPs"
  on public.rsvps for delete
  using (user_id = auth.uid());

-- Policy R5: Select RSVPs (hosts see all for their events, users see who else RSVPed to events they RSVPed to)
create policy "Hosts and RSVPers can see RSVPs"
  on public.rsvps for select
