create policy "Anonymous users cannot view or modify data" on public.group_members for all using (false) with check (false);
create policy "Anonymous users cannot view or modify data" on public.expenses for all using (false) with check (false);
create policy "Anonymous users cannot view or modify data" on public.expense_shares for all using (false) with check (false);

-- Policy R7: Service role has full access
