create policy "Service role has full access" on public.group_members for all using (auth.jwt() ->> 'role' = 'service_role');
create policy "Service role has full access" on public.expenses for all using (auth.jwt() ->> 'role' = 'service_role');
create policy "Service role has full access" on public.expense_shares for all using (auth.jwt() ->> 'role' = 'service_role');

