before insert on public.expense_shares
for each row
execute function public.check_group_membership();

-- Helper function to check if a user_id is in the group of an expense_id
create or replace function public.check_group_membership()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (
    select 1 from public.expenses e
    join public.group_members gm on e.group_id = gm.group_id
    where e.id = new.expense_id
    and gm.user_id = new.user_id
  ) then
    raise exception 'User is not a member of the expense group';
