alter table public.posts enable row level security;

-- Helper function to check if two users are friends (bidirectional accepted)
create or replace function public.is_friends(user_a uuid, user_b uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from public.friendships
    where (requester_id = user_a and addressee_id = user_b)
       or (requester_id = user_b and addressee_id = user_a)
    and status = 'accepted'
  );
$$;

-- Policy R1: Read Posts
create policy "Users can read posts based on audience and friendship"
on public.posts
for select
using (
  audience = 'public'
  or audience = 'friends' and public.is_friends(auth.uid(), author_id)
  or author_id = auth.uid()
);

-- Policy R1 (Anonymous): Read Public Posts Only
create policy "Anonymous users can read public posts only"
on public.posts
for select
using (
  audience = 'public'
  and auth.jwt()->>'role' = 'anonymous'
);

-- Policy R2: Write, Edit, Delete Own Posts
create policy "Users can manage their own posts"
on public.posts
for all
using ( author_id = auth.uid() );

-- Policy R3: Send Friend Requests (Requester)
create policy "Users can send friend requests"
on public.friendships
for insert
with check (
  requester_id = auth.uid()
  and status = 'pending'
);

-- Policy R4: Addressee can accept pending requests
create policy "Addressee can accept pending friend requests"
on public.friendships
for update
using (
  addressee_id = auth.uid()
  and status = 'pending'
);

-- Policy R4: Prevent requester from updating status (only addressee can update)
-- This is implicitly handled by the 'for update' policy above which restricts updates to addressee.
-- However, to be explicit about preventing requester updates on status:
create policy "Requesters cannot update friendship status"
on public.friendships
for update
using (
  requester_id = auth.uid()
  and status != 'pending'
);

-- Policy R5: Either person can delete a friendship or request
create policy "Users can delete friendships they are part of"
on public.friendships
for delete
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

-- Policy R5: Users can see friendships they are part of (Read)
create policy "Users can view friendships they are part of"
on public.friendships
for select
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

-- Policy R6: Service role has full access
revoke all on public.friendships from anon, authenticated;
revoke all on public.posts from anon, authenticated;
grant all on public.friendships to service_role;
grant all on public.posts to service_role;
