create policy "Allow editing own posts" on public.posts for update using (auth.uid() = author_id) with check (auth.uid() = author_id);
create policy "Allow deleting own posts" on public.posts for delete using (auth.uid() = author_id);
-- Prevent changing author_id via update
create policy "Prevent changing author" on public.posts for update using (true) with check (auth.uid() = author_id);

-- R3: Send Friend Requests (Requester can insert)
-- Constraint ensures new requests are pending, but RLS allows the insert if the user is the requester
create policy "Allow sending friend requests" on public.friendships for insert with check (requester_id = auth.uid());

-- R4: Accept Friend Requests (Only addressee of pending request)
create policy "Allow accepting friend requests" on public.friendships for update using (
  auth.uid() = addressee_id and status = 'pending'
);
