-- Enable RLS on the table
alter table public.saved_searches enable row level security;

-- Create a function to check if the email in the row matches the user's verified email
create or replace function public.is_valid_notify_email()
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  return case
    when nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'email' is null then false
    when nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'email' = '' then false
    else true
  end;
end;
$$;

-- Policy for INSERT: Users can only insert their own searches with valid notify_email
create policy "Users can insert their own saved searches"
on public.saved_searches
for insert
with check (
  auth.uid() = user_id
  and (notify_email is null or notify_email = lower(nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'email'))
);

-- Policy for SELECT: Users can only read their own searches
create policy "Users can read their own saved searches"
on public.saved_searches
for select
using (
  auth.uid() = user_id
);

-- Policy for UPDATE: Users can only update their own searches with valid notify_email
create policy "Users can update their own saved searches"
on public.saved_searches
for update
using (
  auth.uid() = user_id
  and (notify_email is null or notify_email = lower(nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'email'))
);

-- Policy for DELETE: Users can only delete their own searches
create policy "Users can delete their own saved searches"
on public.saved_searches
for delete
using (
  auth.uid() = user_id
);

-- Grant full access to the service role for server-side jobs
grant all on public.saved_searches to service_role;
grant all on function public.is_valid_notify_email() to service_role;
