using (contract_id in (select id from public.contracts where owner_id = auth.uid()))
with check (
  -- This check is implicitly handled by the using clause ensuring only owners can trigger the delete
  -- But we need to ensure the user deleting is the owner.
  -- Since RLS 'delete' uses 'using' to decide if a row is deletable, and we want ONLY owner to delete ANY share of their contract.
