create policy "Users can read shared contracts" on public.contracts for select
using (id in (
  select contract_id from public.contract_shares where user_id = auth.uid()
));

-- R5: Users can see share rows of contracts they own or shares addressed to them
create policy "Users can see relevant shares" on public.contract_shares for select
using (user_id = auth.uid());

-- R5: Users can insert shares for contracts they own or add shares to themselves
create policy "Users can insert shares for owned contracts or themselves" on public.contract_shares for insert
using (
  (owner_id = auth.uid() and contract_id in (select id from public.contracts where owner_id = auth.uid()))
  or (user_id = auth.uid())
)
with check (
  (owner_id = auth.uid() and contract_id in (select id from public.contracts where owner_id = auth.uid()))
  or (user_id = auth.uid())
);

-- R5: Users can delete shares they added (if they are the user_id)
create policy "Users can delete their own shares" on public.contract_shares for delete
using (user_id = auth.uid());

