using (
  contract_id in (
    select id from public.contracts where owner_id = auth.uid()
  )
  or contract_id in (
    select contract_id from public.contract_shares where user_id = auth.uid()
  )
)
with check (
  contract_id in (
    select id from public.contracts where owner_id = auth.uid()
  )
  or contract_id in (
    select contract_id from public.contract_shares where user_id = auth.uid()
  )
);

