using (contract_id in (select id from public.contracts where owner_id = auth.uid()))
with check (contract_id in (select id from public.contracts where owner_id = auth.uid()));

-- R4: Only owner can manage shares (insert, update, delete)
-- Note: We restrict insert to owner creating shares for their contract, update to owner modifying shares, delete to owner removing shares.
