-- Enable RLS on both tables
alter table public.moderators enable row level security;
alter table public.listings enable row level security;

-- Helper function to check if user is a moderator
create or replace function public.is_moderator()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.moderators where user_id = auth.uid()
  );
$$;

-- Policy R1: Anyone can see active, not flagged, not deleted listings
create policy "Public listings visibility"
on public.listings
for select
using (
  status = 'active' 
  and is_flagged = false 
  and deleted_at is null
);

-- Policy R2: Sellers can see their own listings; Moderators can see all
create policy "Sellers and Moderators list visibility"
on public.listings
for select
using (
  auth.uid() = seller_id 
  or public.is_moderator()
);

-- Policy R3: Sellers can create listings (not flagged/deleted)
create policy "Sellers create listings"
on public.listings
for insert
with check (
  auth.uid() = seller_id 
  and is_flagged = false 
  and deleted_at is null
);

-- Policy R3 (part 2): Sellers can edit their own non-deleted listings
create policy "Sellers update own non-deleted listings"
on public.listings
for update
using (
  auth.uid() = seller_id 
  and deleted_at is null
);

-- Policy R4: Sellers can soft-delete their own listings
create policy "Sellers soft-delete own listings"
on public.listings
for update
using (
  auth.uid() = seller_id 
  and deleted_at is null
);

-- Policy R5: Moderators can update any listing (flag/unflag, status, etc.)
create policy "Moderators update any listing"
on public.listings
for update
using (
  public.is_moderator()
);

-- Policy R6: Nobody can hard-delete listings (prevent setting deleted_at to non-null via update if it was null, or deleting rows)
-- Since we allow soft delete via update, we must prevent DELETE statements entirely.
create policy "Prevent hard delete of listings"
on public.listings
for delete
using (
  false
);

-- Policy R6: Nobody can modify the moderators table
create policy "Prevent modification of moderators table"
on public.moderators
for all
using (
  false
);

-- Grant service_role full access for server-side operations (R7)
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;
grant all on all sequences in schema public to service_role;
