-- Helper function to check if user owns the survey
create or replace function public.survey_owner_check()
returns boolean as $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    return false;
  end if;
  return exists (
    select 1 from public.surveys where owner_id = v_user_id
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if user owns the survey OR is the service role
create or replace function public.survey_full_access_check()
returns boolean as $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    return false;
  end if;
  -- Service role bypasses RLS, but this function is for policies using RLS
  if current_setting('request.jwt.claims', true) is not null and 
     current_setting('request.jwt.claims', true)::jsonb ->> 'role' = 'service_role' then
    return true;
  end if;
  return exists (
    select 1 from public.surveys where owner_id = v_user_id
  );
end;
$$ language plpgsql security definer;

