  v_org_id bigint;
  v_user_id uuid;
  v_email text;
  v_invite public.invites;
begin
  -- Check if user is signed in
  if auth.jwt().role != 'authenticated' then
    raise exception 'User must be signed in to accept an invite';
  end if;

