-- Enable RLS on storage.objects
alter table storage.objects enable row level security;

-- Helper function to parse object metadata for user claims
create function storage.check_object_ownership() returns trigger as $$
begin
    -- Ensure owner claim matches auth.uid() for write/delete operations
    if (TG_OP = 'DELETE' or TG_OP = 'UPDATE') then
        if (COALESCE(NEW.owner, OLD.owner) is not null and COALESCE(NEW.owner, OLD.owner) != auth.uid()) then
            raise foreign key violation using message = 'Object ownership mismatch';
        end if;
    end if;
    return new;
end;
$$ language plpgsql security definer;

-- Policy R1: Anyone can read objects in 'avatars' bucket
create policy "Anyone can read avatars"
on storage.objects for select
using ( bucket_id = 'avatars' );

-- Policy R2: Authenticated users can manage only their own avatars
create policy "Authenticated users manage own avatars"
on storage.objects for all
using (
    bucket_id = 'avatars'
    and (
        name = (select id from auth.users where auth.uid() = auth.uid())
        or
        name = concat((select id from auth.users where auth.uid() = auth.uid()), '.)')
    )
    and owner = auth.uid()
);

-- Policy R3: Restrict access to other buckets (explicit deny via implicit logic in R1/R2 exclusions)
-- By default, RLS blocks access if no allow policy matches. R1 and R2 only cover 'avatars'.

-- Policy R4: Anonymous users cannot upload/update/delete (handled by R2 requiring auth.uid() and implicit auth check)
-- Explicitly ensure anonymous users can't bypass via metadata if they somehow triggered a write
-- (Note: Supabase JS client requires session for write, but RLS enforces at DB level)

-- Policy R5: Service role has full access (handled by service_role bypassing RLS, no explicit policy needed)
-- However, to be explicit for any potential service role logic that might not bypass (e.g., legacy), we can rely on default service_role behavior.
-- No explicit policy required for service_role as it bypasses RLS by default.

-- Trigger to enforce ownership consistency on insert/update/delete
create trigger enforce_object_ownership
before insert or update or delete on storage.objects
for each row execute function storage.check_object_ownership();

-- Grant necessary permissions to ensure policies work correctly with auth
-- Users need INSERT, UPDATE, DELETE, SELECT on storage.objects
grant all on storage.objects to authenticated;
grant select on storage.objects to anon;

-- Ensure storage buckets are accessible for listing (if needed for app logic)
-- Note: Bucket listing is often handled by RLS on storage.buckets or client-side filtering
-- Assuming standard Supabase setup where bucket listing is controlled separately or via RLS on buckets.
-- If strict isolation is needed for buckets:
alter table storage.buckets enable row level security;
create policy "Anonymous can list buckets" on storage.buckets for select using (true);
create policy "Authenticated can list buckets" on storage.buckets for select using (true);
-- Note: Bucket policies are typically managed by Supabase admin or specific RLS rules.
-- For this schema, we focus on objects as per requirements.
```

