-- Enable RLS on all tables
alter table public.approvers enable row level security;
alter table public.purchase_orders enable row level security;
alter table public.po_approvals enable row level security;

-- Helper function to check if user is an approver
create or replace function public.is_approver(user_id uuid)
returns boolean
language sql
stable
as $$
  select exists (select 1 from public.approvers where user_id = auth.uid() and limit_amount >= (select amount from public.purchase_orders where id = (select po_id from public.po_approvals where approver_id = auth.uid() and decision is not null limit 1)))
$$;

-- R6: Anonymous visitors cannot see or change anything
create policy "Deny anonymous access" on public.approvers for all using (auth.role() = 'authenticated');
create policy "Deny anonymous access" on public.purchase_orders for all using (auth.role() = 'authenticated');
create policy "Deny anonymous access" on public.po_approvals for all using (auth.role() = 'authenticated');

-- R7: Service role keeps full access (handled by bypassing RLS, but explicit grants for clarity if needed elsewhere)
-- Note: service_role bypasses RLS by default in Supabase, so no specific policy needed for full access.

-- R5: Users can see their own row in approvers. Nobody can change approvers through the app.
create policy "Users view own approver row" on public.approvers for select using (auth.uid() = user_id);
create policy "Deny all modifications to approvers" on public.approvers for all using (false);

-- R1 & R2: Requesters can see/edit/delete their own POs; Approvers can see all POs
create policy "Requesters view own POs, Approvers view all" on public.purchase_orders for select
  using (
    auth.uid() = requester_id 
    or exists (select 1 from public.approvers where user_id = auth.uid())
