-- Enable RLS on all tables
alter table public.locations enable row level security;
alter table public.location_staff enable row level security;
alter table public.stock enable row level security;

-- Helper function to check if user is auditor
create or replace function public.is_auditor()
returns boolean
language sql stable
security definer
set search_path = public
as $$
select case
  when jsonb_extract_path_text(auth.jwt(), 'app_metadata', 'role') = 'auditor' then true
  else false
end;
$$;

-- Helper function to check if user is staff at a location
create or replace function public.is_staff(user_id uuid, location_id bigint)
returns boolean
language sql stable
security definer
set search_path = public
as $$
select exists (
  select 1 from public.location_staff
  where location_staff.user_id = user_id
  and location_staff.location_id = location_id
);
$$;

-- Helper function to check if stock is frozen
create or replace function public.is_location_frozen(location_id bigint)
returns boolean
language sql stable
security definer
set search_path = public
as $$
select is_frozen from public.locations where id = location_id;
$$;

-- R6: Anonymous visitors cannot see or change anything
create policy "Anonymous users cannot view or modify data" on public.locations for all using (false) with check (false);
create policy "Anonymous users cannot view or modify data" on public.location_staff for all using (false) with check (false);
create policy "Anonymous users cannot view or modify data" on public.stock for all using (false) with check (false);

-- R7: Service role has full access (handled by service_role role bypassing RLS, but explicit policy for clarity if needed)
-- Note: service_role bypasses RLS entirely, so no policies needed for service_role specifically.
-- However, we ensure authenticated users can't bypass.

-- R1 & R4: Locations view (Signed-in users can see list)
create policy "Allow authenticated users to view locations" on public.locations for select using (auth.role() = 'authenticated');

-- R1: Stock and Staff list view
-- Staff: See stock and staff list of their own locations
create policy "Staff see own location stock and staff list" on public.stock for select using (
  auth.role() = 'authenticated' 
  and public.is_staff(auth.uid(), location_id)
);
create policy "Staff see own location staff list" on public.location_staff for select using (
  auth.role() = 'authenticated' 
  and public.is_staff(auth.uid(), location_id)
);

-- Auditors: See all stock and all staff lists
create policy "Auditors see all stock" on public.stock for select using (public.is_auditor());
create policy "Auditors see all staff list" on public.location_staff for select using (public.is_auditor());

-- R4: Auditors can never change stock
create policy "Auditors cannot modify stock" on public.stock for all using (not public.is_auditor()) with check (not public.is_auditor());

-- R2 & R3: Stock modifications (add, change, remove)
-- Conditions:
-- 1. Must be authenticated
-- 2. Must be staff at the location (for insert/update) OR staff at the location_id in the row (for delete)
-- 3. Location must not be frozen (for insert/update)
-- Note: For updates, we also need to ensure the user is staff at the location_id. 
