-- Enable RLS on all tables
alter table public.folders enable row level security;
alter table public.folder_grants enable row level security;
alter table public.documents enable row level security;

-- Helper function to check if user owns or has grant on a folder (directly or via ancestor)
create or replace function public.has_access_to_folder(p_folder_id bigint, p_role text)
returns boolean
language plpgsql
stable
as $$
declare
  v_has_ownership boolean;
  v_has_edit_grant boolean;
  v_folder_id bigint;
  v_parent_id bigint;
begin
  -- If anonymous, always deny
  if p_role = 'anon' then
    return false;
  end if;

  -- Check ownership chain
  v_has_ownership := false;
  for v_folder_id in (
    select id from public.folders
    where id = p_folder_id
    union all
    select f.id from public.folders f
    inner join public.folders p on f.parent_id = p.id
    where p.id = p_folder_id
  ) loop
    if v_folder_id.owner_id = auth.uid() then
      v_has_ownership := true;
      exit;
    end if;
  end loop;

  -- Check grant chain
  v_has_edit_grant := false;
  for v_folder_id in (
    select id from public.folders
    where id = p_folder_id
    union all
    select f.id from public.folders f
    inner join public.folders p on f.parent_id = p.id
    where p.id = p_folder_id
  ) loop
    if exists (
      select 1 from public.folder_grants fg
      where fg.folder_id = v_folder_id
      and fg.user_id = auth.uid()
      and fg.can_edit = true
    ) then
      v_has_edit_grant := true;
      exit;
    end if;
  end loop;

  -- Return true if user owns the folder/ancestor OR has edit grant on folder/ancestor
  return v_has_ownership or v_has_edit_grant;
end;
$$;

-- Policy for folders: Read access based on ownership or grants (R1)
create policy "Allow read access to folders based on ownership or grants"
on public.folders
for select
using (
  has_access_to_folder(id, auth.role())
);

