on public.folders
for insert
with check (
  parent_id is null
  and owner_id = auth.uid()
);

-- Policy for folders: Update only if user owns or has grant on the folder (R1, R3)
create policy "Allow update of folders based on ownership or grants"
on public.folders
for update
using (
  has_access_to_folder(id, auth.role())
);

-- Policy for folders: Delete only if user owns or has grant on the folder (R1, R3)
create policy "Allow delete of folders based on ownership or grants"
on public.folders
for delete
using (
  has_access_to_folder(id, auth.role())
);

-- Policy for folder_grants: Users can only see grants for folders they own or have access to (R4)
create policy "Allow read access to folder grants based on folder access"
on public.folder_grants
for select
using (
  has_access_to_folder(folder_id, auth.role())
);

-- Policy for folder_grants: Users can only insert grants for folders they own or have access to (R3)
create policy "Allow insert of folder grants based on folder access"
on public.folder_grants
for insert
with check (
  has_access_to_folder(folder_id, auth.role())
