-- Enable RLS on all tables
alter table public.ops_team enable row level security;
alter table public.access_requests enable row level security;
alter table public.access_approvals enable row level security;

-- Helper function to check if user is in ops_team
create or replace function public.is_ops_member(user_id uuid) returns boolean as $$
  select exists (select 1 from public.ops_team where user_id = $1);
$$ language sql stable;

-- View to show ops team members (Rule R1)
create or replace view public.ops_team_view as
  select user_id from public.ops_team;

-- Policy for ops_team view (Rule R1)
create policy "Ops team can see all members" on public.ops_team_view
  for select using (true);

-- Policy for access_requests: Select (Rule R1, R5)
create policy "Users see own requests, ops see all" on public.access_requests
  for select
  using (
    auth.uid() = requester_id
    or public.is_ops_member(auth.uid())
  );

-- Policy for access_approvals: Select (Rule R1, R5)
create policy "Users see own approvals, ops see all" on public.access_approvals
  for select
  using (
    approver_id = auth.uid()
    or public.is_ops_member(auth.uid())
  );

-- Policy for access_requests: Insert (Rule R2, R5)
create policy "Users can create own requests" on public.access_requests
  for insert
  with check (auth.uid() = requester_id);

-- Policy for access_requests: Delete (Rule R2, R5)
create policy "Users can delete own pending requests" on public.access_requests
  for delete
  using (
    requester_id = auth.uid()
    and status = 'pending'
  );

-- Policy for access_requests: Update (Rule R3 - blocked except via RPC)
-- We create a policy that allows NO direct updates, relying on the RPC to handle logic
-- However, to strictly follow "Nobody can change requests... except through approve_access",
-- we must ensure no direct UPDATE policy exists.
-- The default behavior without an UPDATE policy is to deny all.
-- We will explicitly create a policy that denies direct updates to ensure R3 compliance.
create policy "Block direct updates to requests" on public.access_requests
  for update
  using (false)
  with check (false);

-- Policy for access_approvals: Insert (Rule R3 - blocked except via RPC)
create policy "Block direct inserts to approvals" on public.access_approvals
  for insert
  using (false)
  with check (false);

-- Policy for access_approvals: Update/Delete (Rule R3 - blocked except via RPC)
create policy "Block direct updates/deletes to approvals" on public.access_approvals
  for all
  using (false)
  with check (false);

-- Function to approve access (Rule R4)
create or replace function public.approve_access(p_request_id bigint) returns text as $$
declare
  v_request public.access_requests;
  v_approver_id uuid;
  v_count integer;
  v_new_status text;
begin
  -- Check if user is in ops team
  if not public.is_ops_member(auth.uid()) then
    raise exception 'User is not a member of the ops team';
  end if;

  -- Get the request
  select * into v_request
  from public.access_requests
  where id = p_request_id
  for update skip locked;

  -- Check if request exists
  if not found then
    raise exception 'Request not found';
  end if;

  -- Check if request is pending
  if v_request.status != 'pending' then
    raise exception 'Request is not pending';
  end if;

  -- Check if user made the request
  if v_request.requester_id = auth.uid() then
    raise exception 'Requester cannot approve their own request';
  end if;

  -- Check if user already approved
  if exists (
    select 1 from public.access_approvals
    where request_id = p_request_id and approver_id = auth.uid()
  ) then
    raise exception 'You have already approved this request';
  end if;

  -- Record the approval
  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, auth.uid(), now());

  -- Check if two different ops members have approved
  select count(*) into v_count
  from public.access_approvals
  where request_id = p_request_id;

  if v_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
    v_new_status := 'granted';
  else
    v_new_status := 'pending';
  end if;

  return v_new_status;
end;
$$ language plpgsql security definer;

-- Grant service_role full access (Rule R6)
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;
grant all on all views in schema public to service_role;

-- Revoke anonymous access explicitly (Rule R5)
-- Default RLS denies anonymous, but we ensure no implicit grants
revoke all on public.ops_team from anon;
revoke all on public.access_requests from anon;
revoke all on public.access_approvals from anon;
revoke all on public.ops_team_view from anon;
revoke all on function public.approve_access from anon;
