    -- Count unique ops team members who have approved this request
    select count(distinct approver_id) into count_val
    from public.access_approvals
    where request_id = $1
    and is_ops_team_member(approver_id);

    return count_val;
end;
$$ language plpgsql security definer;

-- Policy R1: Select access_requests
