-- Helper function for the RPC logic
create or replace function public.approve_access_logic(p_request_id bigint, p_approver_id uuid)
returns text as $$
declare
    v_request status text;
    v_count bigint;
    v_current_ops_count bigint;
begin
    -- Check if request exists
    if not exists (select 1 from public.access_requests where id = p_request_id) then
        raise exception 'Request not found';
    end if;

    -- Check if request is pending
    select status into v_request from public.access_requests where id = p_request_id;
    if v_request != 'pending' then
        raise exception 'Request is not pending';
    end if;

    -- Check if approver is on ops team
    if not public.is_ops_team_member(p_approver_id) then
        raise exception 'User is not an ops team member';
    end if;

    -- Check if user made the request themselves
    if (select requester_id from public.access_requests where id = p_request_id) = p_approver_id then
        raise exception 'Requester cannot approve their own request';
    end if;

    -- Check if user already approved this request
    if exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = p_approver_id) then
        raise exception 'User has already approved this request';
    end if;

    -- Get current count of unique ops team approvers
    select count(distinct approver_id) into v_current_ops_count
    from public.access_approvals
    where request_id = p_request_id and is_ops_team_member(approver_id);

    -- Update approvals table
    insert into public.access_approvals (request_id, approver_id, approved_at)
