    if (select requester_id from public.access_requests where id = new.request_id) = new.approver_id then
        raise foreign_key_violation using message = 'You cannot approve your own request.';
    end if;

    -- Check if the caller has already approved this request
    if exists (select 1 from public.access_approvals where request_id = new.request_id and approver_id = new.approver_id) then
        raise foreign_key_violation using message = 'You have already approved this request.';
    end if;

