-- Note: We use a trigger to handle the complex logic of "recipes they can read"
-- because RLS on INSERT cannot directly reference the target table's security policies in a self-referential manner easily
-- without a helper trigger function that checks permissions.
create policy "Allow insert for user"
  on public.favorites
  for insert
