set search_path = public
as $$
begin
  -- Check if the user can read the recipe being favorited
  -- This logic mirrors the 'can_read_recipe' function but specifically checks the recipe_id
  if not (
    auth.role() = 'service_role'
    or (
      not exists (
        select 1
        from public.recipes r
        where r.id = NEW.recipe_id
        and r.is_public = true
      )
      and (
        not exists (
          select 1
          from public.recipes r
          where r.id = NEW.recipe_id
          and r.author_id = auth.uid()
        )
      )
    )
  ) then
    raise exception 'Cannot favorite this recipe';
  end if;
  return new;
end;
$$;

