          where r.id = NEW.recipe_id
          and r.author_id = auth.uid()
        )
      )
    )
  ) then
    raise exception 'Cannot favorite this recipe';
  end if;
  return new;
end;
$$;

create trigger trigger_enforce_favorite_recipe_visibility
  before insert on public.favorites
  for each row
