```sql
-- Enable RLS on all tables
alter table public.events enable row level security;
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.judges enable row level security;
alter table public.submissions enable row level security;

-- Helper function to check if user is a judge for a specific event
create or replace function public.is_judge(user_id uuid, event_id bigint)
returns boolean
language sql stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.judges
    where judges.user_id = user_id
    and judges.event_id = event_id
  );
$$;

-- Helper function to check if user is a team member of a specific team
create or replace function public.is_team_member(user_id uuid, team_id bigint)
returns boolean
language sql stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.team_members
    where team_members.user_id = user_id
    and team_members.team_id = team_id
  );
$$;

-- Helper function to check if submission is past deadline
create or replace function public.is_past_deadline(event_id bigint)
returns boolean
language sql stable
security definer
set search_path = public
as $$
  select now() > (
    select deadline from public.events
    where events.id = event_id
  );
$$;

-- Grants for service_role to bypass RLS
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;
grant all on all sequences in schema public to service_role;

-- Policy for events: Everyone can read, only service_role can modify (via RLS bypass)
-- R1: Signed-in users can see every event
create policy "Events read access for all" on public.events for select
using ( true );

-- R5: Nobody can change events through the app
create policy "Events no write for app" on public.events for all
using ( auth.jwt() is null );

-- Policy for teams: Everyone can read, only service_role can modify
-- R1: Signed-in users can see every team
create policy "Teams read access for all" on public.teams for select
using ( true );

-- R5: Nobody can change teams through the app
create policy "Teams no write for app" on public.teams for all
using ( auth.jwt() is null );

-- Policy for team_members: Users can read their own memberships, service_role can read/write
-- R1: Users can see their own team memberships
create policy "Team members read own membership" on public.team_members for select
using ( auth.uid() = user_id );

-- R1: Signed-in users can see every team (covered by teams select policy)
-- R5: Nobody can change memberships through the app
create policy "Team members no write for app" on public.team_members for all
using ( auth.jwt() is null );

-- Policy for judges: Users can read, only service_role can modify
-- R5: Nobody can change judges through the app
create policy "Judges no write for app" on public.judges for all
using ( auth.jwt() is null );

-- Policy for submissions: Complex logic based on R2, R3, R4
create policy "Submissions read/write logic" on public.submissions for all
using (
  -- R6: Anonymous visitors cannot see or change anything
  (auth.jwt() is not null)
  and (
    -- R1: Users can see their own team memberships (indirectly via team_id check)
    -- But R1 says "Users can see their own team memberships", it doesn't explicitly say they can see team submissions unless they are members.
    -- However, R2 says "Team members can see their own team's submission".
    -- So, if user is a team member of the team that owns the submission, they can read.
    -- Also, Judges can see submissions of their event after deadline.

    -- Check if user is a team member of the team owning this submission
    public.is_team_member(auth.uid(), submissions.team_id)
    -- OR
    -- Check if user is a judge of the team's event and deadline has passed
    or (
      exists (
        select 1 from public.teams t
        join public.events e on e.id = t.event_id
        where t.id = submissions.team_id
        and public.is_judge(auth.uid(), e.id)
        and public.is_past_deadline(e.id)
      )
    )
  )
);

-- R3: Team members can create and edit their own team's submission until the event's deadline
-- This is handled by the `using` clause in the `update` and `insert` parts of the above policy.
-- However, we need to ensure that writes are restricted by the deadline for team members.
-- The current `using` clause allows reads for past deadlines for judges, but for team members (who are not judges),
-- we need to restrict writes if the deadline has passed.
-- Let's refine the policy to separate insert/update from select if needed, or use `with check` and specific `using` conditions.

-- Refined Submission Policy
drop policy if exists "Submissions read/write logic" on public.submissions;

-- Create policy for SELECT
create policy "Submissions select logic" on public.submissions for select
using (
  (auth.jwt() is not null)
  and (
    public.is_team_member(auth.uid(), submissions.team_id)
    or (
      exists (
        select 1 from public.teams t
        join public.events e on e.id = t.event_id
        where t.id = submissions.team_id
        and public.is_judge(auth.uid(), e.id)
        and public.is_past_deadline(e.id)
      )
    )
  )
);

-- Create policy for INSERT and UPDATE
create policy "Submissions insert/update logic" on public.submissions for all
using (
  (auth.jwt() is not null)
  and (
    -- Must be a team member of the team
    public.is_team_member(auth.uid(), submissions.team_id)
  )
  and (
    -- Can insert/update only if past deadline is false (i.e., deadline not passed)
    not public.is_past_deadline(
      (select event_id from public.teams where id = submissions.team_id)
    )
  )
)
with check (
  (auth.jwt() is not null)
  and (
    public.is_team_member(auth.uid(), submissions.team_id)
  )
  and (
    not public.is_past_deadline(
      (select event_id from public.teams where id = submissions.team_id)
    )
  )
);

-- R4: After the deadline nobody can change submissions through the app
-- (Covered by the `using` clause in the insert/update policy above)
-- R4: Submissions are never deleted.
-- We can achieve this by not allowing DELETE on submissions, or by making the policy restrictive.
-- Since the policy above only allows INSERT and UPDATE for team members (and SELECT for others),
-- it naturally prevents DELETE by default unless we explicitly allow it.
-- To be explicit and safe, let's add a DELETE policy that denies everything except service_role.
create policy "Submissions no delete for app" on public.submissions for delete
using ( false );

-- R6: Anonymous visitors cannot see or change anything.
-- (Covered by `auth.jwt() is not null` checks in all policies)
-- R7: Server-side code using the service role keeps full access.
-- (Covered by grants to service_role)
