    v_project_id bigint;
    v_is_maintainer boolean;
    v_is_reporter boolean;
    v_is_assignee boolean;
    v_is_confidential boolean;
  begin
    -- Get project ID and confidentiality status
    select project_id, is_confidential into v_project_id, v_is_confidential
    from public.issues
    where id = p_issue_id;

    -- Check visibility rules
    if not v_is_confidential then
