  )
  select exists (
    select 1 from issue_data
    where role in ('developer', 'maintainer')
    and i.id = p_issue_id
    and i.reporter_id != p_user_id -- Reporters cannot update
  );
$$;

-- Helper function to check if user can change confidentiality (only maintainer)
create or replace function public.can_change_confidentiality(p_issue_id bigint, p_user_id uuid)
returns boolean
language sql stable
security invoker
as $$
  with issue_data as (
    select i.id, i.project_id, pm.role
    from public.issues i
    left join public.project_members pm on i.project_id = pm.project_id and pm.user_id = p_user_id
    where i.id = p_issue_id
  )
  select exists (
    select 1 from issue_data
    where role = 'maintainer'
  );
$$;

-- Policy: Enable RLS for projects
create policy "Enable RLS for projects" on public.projects
for all using (true);

-- Policy: Members can see their projects and every member of those projects.
