    select 1 from public.project_members
    where project_members.project_id = public.projects.id
    and project_members.user_id = auth.uid()
  )
);

-- Policy: Members can see every non-confidential issue in their projects.
create policy "Members can see non-confidential issues" on public.issues
for select using (
  exists (
    select 1 from public.project_members
    where project_members.project_id = issues.project_id
    and project_members.user_id = auth.uid()
  )
  and issues.is_confidential = false
);

-- Policy: Confidential issues visible only to maintainers, reporter, assignee.
create policy "Members can see confidential issues" on public.issues
for select using (
  exists (
    select 1 from public.project_members
    where project_members.project_id = issues.project_id
    and project_members.user_id = auth.uid()
  )
  and issues.is_confidential = true
  and (
    issues.reporter_id = auth.uid()
    or issues.assignee_id = auth.uid()
    or public.is_member_of_project(issues.project_id, auth.uid(), 'maintainer')
  );
);

-- Policy: Members can file issues in their projects as the reporter, confidential or not.
create policy "Members can file issues" on public.issues
for insert with check (
  exists (
    select 1 from public.project_members
    where project_members.project_id = issues.project_id
    and project_members.user_id = auth.uid()
  )
);

-- Policy: Developers and maintainers can update the issues they can see.
create policy "Developers and maintainers can update issues" on public.issues
for update using (
  exists (
    select 1 from public.project_members
    where project_members.project_id = issues.project_id
    and project_members.user_id = auth.uid()
  )
  and public.can_update_issue(issues.id, auth.uid())
);

-- Policy: Only maintainers can make an issue confidential or not confidential.
create policy "Only maintainers can change confidentiality" on public.issues
for update using (
  exists (
    select 1 from public.project_members
    where project_members.project_id = issues.project_id
    and project_members.user_id = auth.uid()
  )
  and public.can_change_confidentiality(issues.id, auth.uid())
);

-- Policy: Prevent deletion of issues.
create policy "Prevent deletion of issues" on public.issues
for delete using (false);

-- Policy: Prevent changes to project_id, reporter_id, assignee_id via update (soft enforcement via application logic, but schema-wise we ensure RLS doesn't allow broad updates).
-- Note: The requirement "nobody can change projects or memberships through the app" usually implies preventing updates to project_id in issues or role in project_members.
-- Since we are not modifying existing tables, we rely on the insert policy for issues and the lack of update policy for project_members.
-- To strictly prevent updating project_id in issues via update:
create policy "Prevent updating project_id in issues" on public.issues
for update using (false);

-- Policy: Prevent updating role in project_members.
create policy "Prevent updating role in project_members" on public.project_members
for update using (false);

-- Policy: Prevent updating user_id in project_members (changes to membership).
create policy "Prevent updating user_id in project_members" on public.project_members
for update using (false);

-- Policy: Anonymous visitors cannot see or change anything.
create policy "Anonymous cannot see anything" on public.projects
for select using (false);
create policy "Anonymous cannot insert issues" on public.issues
for insert with check (false);
create policy "Anonymous cannot update issues" on public.issues
for update using (false);
create policy "Anonymous cannot see project_members" on public.project_members
for select using (false);

-- Policy: Service role has full access.
create policy "Service role has full access" on public.projects
for all using (true);
create policy "Service role has full access" on public.project_members
for all using (true);
create policy "Service role has full access" on public.issues
for all using (true);

-- Grant necessary permissions to authenticated users to call helper functions
grant execute on function public.is_member_of_project(bigint, uuid, text) to authenticated;
grant execute on function public.get_max_role_in_project(bigint, uuid) to authenticated;
grant execute on function public.can_see_issue_confidential(bigint, uuid) to authenticated;
grant execute on function public.can_update_issue(bigint, uuid) to authenticated;
grant execute on function public.can_change_confidentiality(bigint, uuid) to authenticated;

