-- Enable Row Level Security on all tables
alter table public.pharmacists enable row level security;
alter table public.prescriptions enable row level security;
alter table public.dispenses enable row level security;

-- ==========================================
-- 1. Helper Functions & Triggers
-- ==========================================

-- Function to handle the dispense logic with business rules
create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_prescription record;
  v_pharmacist_id uuid;
  v_refills_left integer;
begin
  -- Fetch prescription details
  select p.*, u.id into v_prescription
  from public.prescriptions p
  join auth.users u on u.id = p.patient_id
  where p.id = p_prescription_id;

  -- Check if prescription exists
  if not found then
    raise exception 'Prescription not found';
  end if;

  -- Get current user (pharmacist)
  v_pharmacist_id := auth.uid();

  -- Rule 4: Check if caller is a pharmacist
  if not exists (select 1 from public.pharmacists where user_id = v_pharmacist_id) then
    raise exception 'Caller must be a pharmacist';
  end if;

  -- Rule 4: Check if prescription is the caller's own
  if v_prescription.patient_id = v_pharmacist_id then
    raise exception 'Pharmacists cannot dispense their own prescriptions';
  end if;

  -- Rule 4: Check if prescription has expired
  if v_prescription.expires_at < now() then
    raise exception 'Prescription has expired';
  end if;

  -- Rule 4: Check if refills left > 0
  if v_prescription.refills_left <= 0 then
    raise exception 'No refills left';
  end if;

  -- Decrement refills
  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id;

  -- Record dispense
  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist_id, now());

  -- Return updated refills left
  return (select refills_left from public.prescriptions where id = p_prescription_id);
end;
$$;

-- Trigger to auto-fire dispense function? 
-- Note: The requirement says "Implement it as public.rpc", implying a manual call, 
-- but R3 says "records a dispense". The function does the recording. 
-- No trigger needed unless automatic recording on some other event is required.
-- Based on R4 ("dispense must raise an error..."), the explicit function call is the correct path.

-- ==========================================
-- 2. Row Level Security Policies
-- ==========================================

-- Table: pharmacists
-- R1: Signed-in users can see who the pharmacists are.
-- Everyone with a session (not anon) can read pharmacists.
create policy "Allow authenticated users to view pharmacists"
on public.pharmacists
for select
using (auth.role() = 'authenticated');

-- Table: prescriptions
-- R1: Patients can see their own prescriptions; Pharmacists can see every prescription.
-- Authenticated users can read, but specific logic applied in 'using' clause.
create policy "Prescriptions visibility based on role"
on public.prescriptions
for select
using (
  auth.role() = 'authenticated' 
  AND (
    -- Pharmacists (verified via row check or just role? Schema doesn't define a 'pharmacist' role in auth.users, 
    -- but we have a pharmacists table. However, RLS 'using' clauses can't easily join tables without overhead.
    -- Let's assume 'pharmacists' table rows are linked to auth.users. 
    -- To be safe and efficient: Allow if user is in pharmacists table OR user is the patient.
    EXISTS (SELECT 1 FROM public.pharmacists WHERE user_id = auth.uid())
    OR auth.uid() = patient_id
  )
);

-- R2: Nobody can create, change or delete prescriptions directly through the app.
-- Deny all mutations for authenticated users.
create policy "Deny direct prescription mutations"
on public.prescriptions
for all
to authenticated
using (false);

-- Allow service_role to do everything (R6)
create policy "Allow service role full access to prescriptions"
on public.prescriptions
for all
to service_role;

-- Table: dispenses
-- R1: Patients can see their own dispenses; Pharmacists can see every dispense.
create policy "Dispenses visibility based on role"
on public.dispenses
for select
using (
  auth.role() = 'authenticated'
  AND (
    EXISTS (SELECT 1 FROM public.pharmacists WHERE user_id = auth.uid())
    OR auth.uid() = (select patient_id from public.prescriptions where id = prescription_id)
  )
);

-- R2: Nobody can create, change or delete dispenses directly through the app.
-- The creation happens via the RPC function which uses service_role context internally or the function itself.
-- If the RPC is called by the frontend with the patient's token, we need to ensure they can't bypass the function.
-- Since the requirement says "Implement it as public.rpc", the frontend calls the function.
-- The function logic validates the user. The RLS policy should block direct row insertion.
create policy "Deny direct dispense mutations"
on public.dispenses
for all
to authenticated
using (false);

-- Allow service_role to do everything (R6)
create policy "Allow service role full access to dispenses"
on public.dispenses
for all
to service_role;

-- ==========================================
-- 3. Grants & Revokes
-- ==========================================

-- Ensure no public access (already implicit in Supabase, but explicit for clarity)
revoke all on public.pharmacists from public;
revoke all on public.prescriptions from public;
revoke all on public.dispenses from public;

-- Ensure anon cannot see anything (R5)
revoke all on public.pharmacists from anon;
revoke all on public.prescriptions from anon;
revoke all on public.dispenses from anon;

-- Grant necessary permissions to authenticated users for reading (handled by policies, but ensure select is allowed)
grant select on public.pharmacists to authenticated;
grant select on public.prescriptions to authenticated;
grant select on public.dispenses to authenticated;

-- Grant all to service_role (handled by policies, but ensure underlying permission exists)
grant all on public.pharmacists to service_role;
grant all on public.prescriptions to service_role;
grant all on public.dispenses to service_role;
