-- Helper function to check SSO requirement
create or replace function public.check_sso_requirement()
returns boolean as $$
declare
  v_has_sso boolean;
begin
  select (array_agg(method) @> array['sso/saml']) into v_has_sso
  from auth.jwt()
  where method = 'sso/saml';
  return v_has_sso;
end;
$$ language plpgsql security definer;

-- Helper function to check if user is an admin of the org
create or replace function public.is_org_admin(org_id bigint)
returns boolean as $$
declare
  v_is_admin boolean;
begin
  select (role = 'admin') into v_is_admin
  from public.org_members
  where org_id = org_id and user_id = auth.uid();
  return v_is_admin;
end;
$$ language plpgsql security definer;

-- Helper function to check if user is a member of the org
create or replace function public.is_org_member(org_id bigint)
returns boolean as $$
declare
  v_is_member boolean;
begin
  select (user_id = auth.uid()) into v_is_member
  from public.org_members
  where org_id = org_id;
  return v_is_member;
end;
$$ language plpgsql security definer;

-- Helper function to check if user is a member of the org AND (admin OR SSO required)
create or replace function public.can_access_org(org_id bigint)
returns boolean as $$
declare
  v_is_member boolean;
  v_is_admin boolean;
  v_has_sso boolean;
begin
  select (user_id = auth.uid()) into v_is_member
  from public.org_members
  where org_id = org_id;

  select (role = 'admin') into v_is_admin
  from public.org_members
  where org_id = org_id and user_id = auth.uid();

  select (array_agg(method) @> array['sso/saml']) into v_has_sso
  from auth.jwt()
  where method = 'sso/saml';

  -- If org requires SSO, only admins with SSO can access
  if (select require_sso from public.orgs where id = org_id) then
    return v_is_admin and v_has_sso;
  else
    return v_is_member;
  end if;
end;
$$ language plpgsql security definer;

