-- Enable RLS on both tables
alter table public.documents enable row level security;
alter table public.doc_access enable row level security;

-- Policy R5: Anonymous users cannot see or change anything
create policy anon_block on public.documents for all using (false) with check (false);
create policy anon_block on public.doc_access for all using (false) with check (false);

-- Policy R6: Service role has full access
create policy service_role_full_access on public.documents for all using (true);
create policy service_role_full_access on public.doc_access for all using (true);

-- Policy R1: Users can read documents they have access to (any row)
create policy user_read_documents on public.documents for select
  using (exists (
    select 1 from public.doc_access da 
    where da.doc_id = public.documents.id 
    and da.user_id = auth.uid()
  ));

-- Policy R1: Users can read their own access rows (schema implies they can read the access table if they own the row, but typically we restrict access to just the doc_access table for editing permissions. However, the rule says "read the documents they have access to (any row in doc_access) and their own access rows". This implies SELECT on doc_access is allowed for the user's own rows.)
create policy user_read_own_access on public.doc_access for select
  using (user_id = auth.uid());

-- Policy R2: No direct CREATE, UPDATE, DELETE on documents or doc_access
-- DROP is handled by 'for all' with check=false or specific deny, but 'for insert/update/delete' with using check=false covers it.
-- We explicitly deny direct mutations.
create policy no_direct_insert on public.documents for insert with check (false);
create policy no_direct_update on public.documents for update using (false);
create policy no_direct_delete on public.documents for delete using (false);
create policy no_direct_insert on public.doc_access for insert with check (false);
create policy no_direct_update on public.doc_access for update using (false);
create policy no_direct_delete on public.doc_access for delete using (false);

-- Function to check out a document
create or replace function public.checkout_document(p_doc_id bigint) returns void language plpgsql security definer set search_path = public as $$
begin
  -- Check if document exists
  if not exists (select 1 from public.documents where id = p_doc_id) then
    raise exception 'Document does not exist';
  end if;

  -- Check if user has edit access
  if not exists (select 1 from public.doc_access where doc_id = p_doc_id and user_id = auth.uid()) then
    raise exception 'User does not have edit access to this document';
  end if;

  -- Check if document is already checked out by someone else
  if exists (select 1 from public.documents where id = p_doc_id and checked_out_by is not null and checked_out_by != auth.uid()) then
    raise exception 'Document is already checked out by another user';
  end if;

  -- Check out the document (set checked_out_by)
  update public.documents 
  set checked_out_by = auth.uid() 
  where id = p_doc_id;
end;
$$;

-- Function to check in a document
create or replace function public.checkin_document(p_doc_id bigint, p_body text) returns void language plpgsql security definer set search_path = public as $$
begin
  -- Check if document exists
  if not exists (select 1 from public.documents where id = p_doc_id) then
    raise exception 'Document does not exist';
  end if;

  -- Check if user currently has the document checked out
  if (select checked_out_by from public.documents where id = p_doc_id) is null or (select checked_out_by from public.documents where id = p_doc_id) != auth.uid() then
    raise exception 'User does not currently have the document checked out';
  end if;

  -- Check in the document (update body and clear checked_out_by)
  update public.documents 
  set body = p_body, 
      checked_out_by = null 
  where id = p_doc_id;
end;
$$;

-- Grant execute on functions to authenticated users (functions are called by app, need to be accessible)
grant execute on function public.checkout_document(bigint) to authenticated;
grant execute on function public.checkin_document(bigint, text) to authenticated;
