  -- Check if already checked out by self
  if exists (
    select 1 from public.documents
    where id = p_doc_id and checked_out_by = auth.uid()
  ) then
    -- Already checked out, succeed (no change)
    return;
  end if;

  -- Lock the document
  update public.documents
  set checked_out_by = auth.uid()
  where id = p_doc_id;
end;
$$;

-- Function: checkin_document
-- R4 Logic: Check if user currently has the document checked out. If yes, save body and release lock.
create or replace function public.checkin_document(p_doc_id bigint, p_body text)
returns void
language plpgsql
security def
set search_path = public
as $$
begin
  -- Check if the caller currently has the document checked out
  if not exists (
    select 1 from public.documents
    where id = p_doc_id and checked_out_by = auth.uid()
  ) then
    raise exception 'You must check out the document before checking it in';
  end if;

  -- Update the body and release the lock
  update public.documents
  set body = p_body,
      checked_out_by = null
  where id = p_doc_id;
end;
$$;
