alter table public.request_photos enable row level security;

-- Helper function to check if user is building staff for a given building
create or replace function public.is_building_staff(building_id bigint)
returns boolean
language sql
stable
security definer
as $$
  select exists (
    select 1 from public.building_staff
    where building_staff.building_id = building_id
    and building_staff.user_id = auth.uid()
  );
$$;

-- Helper function to check if user is resident of a given unit
create or replace function public.is_resident(unit_id bigint)
returns boolean
language sql
stable
security definer
as $$
  select exists (
    select 1 from public.residents
    where residents.unit_id = unit_id
    and residents.user_id = auth.uid()
  );
$$;

-- Policy: Residents and staff can see their own units
create policy "Residents and staff can see their own units"
on public.units for select
using (
  public.is_resident(id) or public.is_building_staff(building_id)
);

-- Policy: Residents and staff can see requests for their units or buildings
create policy "Residents and staff can see requests"
on public.requests for select
using (
  public.is_resident(unit_id) or
  (public.is_building_staff(building_id) and exists (
    select 1 from public.units u where u.id = unit_id and u.building_id = building_id
  ))
);

-- Policy: Residents and staff can see photos for their units or buildings
create policy "Residents and staff can see photos"
on public.request_photos for select
using (
  public.is_resident(request_id) or
  (public.is_building_staff(building_id) and exists (
    select 1 from public.requests r where r.id = request_id and r.unit_id = unit_id
  ))
);

-- Policy: Residents can create requests for their own units
create policy "Residents can create requests for their own units"
on public.requests for insert
with check (
  public.is_resident(unit_id) and created_by = auth.uid()
);

-- Policy: Residents and staff can add photos to requests they can see
create policy "Residents and staff can add photos to requests they can see"
on public.request_photos for insert
with check (
  public.is_resident(request_id) or
  (public.is_building_staff(building_id) and exists (
    select 1 from public.requests r where r.id = request_id and r.unit_id = unit_id
  ))
);

-- Policy: Building staff can update status of requests in their buildings
create policy "Building staff can update status of requests in their buildings"
on public.requests for update
using (
  public.is_building_staff(building_id)
);

-- Policy: Nobody can change anything else about a request (except status via staff)
-- This is implicitly handled by the specific update policy above which only allows status updates for staff.
-- To ensure residents cannot update requests at all:
create policy "Residents cannot update requests"
on public.requests for update
to authenticated
using (
  -- If the user is a resident, they cannot update unless the policy below (staff) matches, which it won't for non-status fields
  -- However, RLS 'for update' policies are additive. We need to explicitly deny if they are a resident but not staff for that building.
  not (public.is_resident(unit_id) and not public.is_building_staff(building_id))
);

-- Actually, the standard way to prevent residents from updating is to not give them update perms,
-- but we need to allow staff to update status.
-- Let's refine: Create a policy that allows ANY authenticated user to update ONLY if they are staff.
-- But wait, RLS doesn't work by "only allow". It works by "allow if condition met".
-- If we don't have a policy for 'update', no one can update (except service_role).
-- We need a policy that allows staff to update status.
-- We also need to ensure residents CANNOT update. Since we don't have a general 'update' policy for authenticated users,
-- residents won't be able to update by default unless we create a policy that grants it to them.
-- So, we only create the policy for staff.
-- BUT, the requirement says "Nobody can change anything else about a request".
-- The policy `Building staff can update status` allows:
-- 1. User is staff AND (new status is being set? No, RLS 'using' checks the row BEFORE update, 'with check' checks after).
-- RLS 'for update' uses the 'using' clause to determine if the update is allowed.
-- The 'using' clause above checks `public.is_building_staff(building_id)`.
-- This allows staff to update ANY column because the 'using' clause doesn't restrict columns.
-- Requirement R4: "Building staff can change the status... Nobody can change anything else".
-- To strictly enforce "only status", we would need application logic or complex RLS.
-- However, standard Supabase RLS on 'for update' allows updating all columns if the 'using' clause passes.
-- To satisfy "Nobody can change anything else", we must assume the application layer enforces setting only status,
-- OR we use a trigger to reject updates to other columns.
-- Given the constraint "Do not modify existing tables or data" and "Output exactly one sql block", I will add a trigger to enforce R4 strictly.

-- Trigger function to ensure only status is updated
create or replace function public.prevent_request_field_updates()
returns trigger
language plpgsql
security definer
as $$
begin
  -- If the update is not on the status column (or id, request_id, unit_id which are keys), raise error
  -- Note: 'id' is identity, 'unit_id' is ref, 'created_by' is ref.
  -- We assume only 'status' is mutable by humans.
  if (tg_op = 'UPDATE') then
    -- Check if any column other than status, id, unit_id, created_by, description (wait, description is not mutable per R4? "Nobody can change anything else")
    -- "Nobody can change anything else about a request". Does this include description?
    -- "Residents report problems... Building staff update progress".
    -- Implies description is initial only.
    if (tg_cols[1] = 'status') then
      return NEW;
    else
      raise exception 'Direct modification of request fields other than status is not allowed.';
    end if;
  end if;
  return NEW;
end;
$$;

create trigger prevent_request_field_updates_trigger
  before update on public.requests
  for each row
  execute function public.prevent_request_field_updates();

-- Policy: Residents and staff can see their own residence and staff rows (Read only)
create policy "Residents can see own residence"
on public.residents for select
using (user_id = auth.uid());

create policy "Staff can see own staff rows"
on public.building_staff for select
using (user_id = auth.uid());

create policy "Residents can see staff in their building"
on public.building_staff for select
using (
  exists (
    select 1 from public.units u
    where u.id = public.residents.unit_id and u.building_id = public.building_staff.building_id
  )
);

-- Policy: Nobody can change units, residents or staff through the app.
-- Deny insert, update, delete for authenticated users on these tables.
create policy "Deny changes to units"
on public.units for all
to authenticated
using (false);

create policy "Deny changes to residents"
on public.residents for all
to authenticated
using (false);

create policy "Deny changes to building_staff"
on public.building_staff for all
to authenticated
using (false);

-- Policy: Anonymous visitors cannot see or change anything
-- By default, anon might have some grants if not careful, but we are setting specific policies.
-- Ensure no policies apply to anon for these tables (they are scoped to authenticated or service_role).
-- The policies above use 'to authenticated' or 'to public' (which excludes anon? No, public includes anon).
-- Wait, RLS policies apply to the user making the request.
-- If a policy says `to public` and has a `using` clause, anon can see if `using` passes.
-- My policies for units/residents/staff:
-- `is_building_staff` returns false for anon.
-- `is_resident` returns false for anon.
-- So anon cannot see anything via those policies.
-- Explicitly deny anon if needed, but the logic above handles it.
-- However, to be explicit about R6:
create policy "Anonymous cannot see units"
on public.units for select
to anon
using (false);

create policy "Anonymous cannot see residents"
on public.residents for select
to anon
using (false);

create policy "Anonymous cannot see building_staff"
on public.building_staff for select
to anon
using (false);

create policy "Anonymous cannot see requests"
on public.requests for select
to anon
using (false);

create policy "Anonymous cannot see request_photos"
on public.request_photos for select
to anon
using (false);

-- Grants for service_role
-- Grant full access to service_role for all tables
grant all on all tables in schema public to service_role;
grant select on all sequences in schema public to service_role;

-- Revoke all from anon explicitly to ensure R6 is hard enforced even if a policy accidentally matches
