-- Enable RLS on tables
alter table public.listings enable row level security;
alter table public.orders enable row level security;

-- Function to check if a user is part of an order (buyer or seller)
create or replace function public.is_order_participant(p_order_id bigint, p_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.orders o
    where o.id = p_order_id and (o.buyer_id = p_user_id or o.seller_id = p_user_id)
  );
end;
$$ language plpgsql security definer;

-- Function to get order details safely
create or replace function public.get_order(p_order_id bigint)
returns public.orders as $$
declare
  v_order public.orders;
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'Order not found';
  end if;
  return v_order;
end;
$$ language plpgsql security definer;

-- Function to get listing details safely
create or replace function public.get_listing(p_listing_id bigint)
returns public.listings as $$
declare
  v_listing public.listings;
begin
  select * into v_listing from public.listings where id = p_listing_id;
  if not found then
    raise exception 'Listing not found';
  end if;
  return v_listing;
end;
$$ language plpgsql security definer;

-- RLS Policies

-- Listings: Signed-in users can see every listing
create policy "Users can view listings" on public.listings
  for select using (auth.role() = 'authenticated');

-- Listings: Service role can insert/update/delete (for admin/internal ops if needed, though spec implies read-only for app)
-- Spec doesn't explicitly forbid server-side listing management, but R1 says signed-in users can see.
-- Assuming app manages listings, we allow authenticated users to manage their own or general management via service role.
-- However, standard marketplace: sellers create listings. Let's allow sellers to manage their own, and service role for bulk.
create policy "Sellers can manage their own listings" on public.listings
  for all using (seller_id = auth.uid()) with check (seller_id = auth.uid());

create policy "Service role full access" on public.listings
  for all using (true) with check (true) with grant option to service_role;

-- Orders: Buyers and sellers can see the orders they are part of
create policy "Users see their own orders" on public.orders
  for select using (public.is_order_partinator(orders.id, auth.uid()) = true);

-- Orders: Insert policy for buyers
-- R2: Buyers place orders as themselves; seller_id and amount must match listing; new orders always pending_payment
create policy "Buyers can create orders for valid listings" on public.orders
  for insert with check (
    buyer_id = auth.uid() and
    exists (select 1 from public.listings l where l.id = orders.listing_id and l.seller_id = orders.seller_id and l.price = orders.amount) and
    orders.buyer_id <> orders.seller_id
  );

-- Orders: Service role full access (for webhooks and functions)
create policy "Service role full access" on public.orders
  for all using (true) with check (true) with grant option to service_role;

-- Functions Implementation

-- mark_shipped: Seller moves paid -> shipped
create or replace function public.mark_shipped(p_order_id bigint)
returns text as $$
declare
  v_order public.orders;
  v_new_status text;
  v_error text;
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'Order not found';
  end if;

  if v_order.buyer_id != auth.uid() then
    raise exception 'Unauthorized: Only the buyer can release funds';
  end if;

  if v_order.seller_id != auth.uid() then
    raise exception 'Unauthorized: Only the seller can mark as shipped';
  end if;

  if v_order.status != 'paid' then
    raise exception 'Order is not in paid status';
  end if;

  -- Note: The prompt says "mark_shipped lets the order's seller move it".
  -- But the description says "release_funds lets the order's buyer move it from shipped to released".
  -- Let's re-read R4 carefully:
  -- R4: "mark_shipped lets the order's seller move it from paid to shipped."
  -- "release_funds lets the order's buyer move it from shipped to released."
  -- So mark_shipped checks seller.
  if v_order.seller_id != auth.uid() then
    raise exception 'Unauthorized: Only the seller can mark as shipped';
  end if;

  v_new_status := 'shipped';
  update public.orders set status = v_new_status where id = p_order_id;
  return v_new_status;
exception when others then
  rollback;
  raise;
end;
$$ language plpgsql security definer;

-- release_funds: Buyer moves shipped -> released
create or replace function public.release_funds(p_order_id bigint)
returns text as $$
declare
  v_order public.orders;
  v_new_status text;
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'Order not found';
  end if;

  if v_order.status != 'shipped' then
    raise exception 'Order is not in shipped status';
  end if;

  if v_order.buyer_id != auth.uid() then
    raise exception 'Unauthorized: Only the buyer can release funds';
  end if;

  v_new_status := 'released';
  update public.orders set status = v_new_status where id = p_order_id;
  return v_new_status;
exception when others then
  rollback;
  raise;
end;
$$ language plpgsql security definer;

-- refund_order: Seller moves paid/shipped -> refunded
create or replace function public.refund_order(p_order_id bigint)
returns text as $$
declare
  v_order public.orders;
  v_new_status text;
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'Order not found';
  end if;

  if v_order.status not in ('paid', 'shipped') then
    raise exception 'Order is not in paid or shipped status';
  end if;

  if v_order.seller_id != auth.uid() then
    raise exception 'Unauthorized: Only the seller can refund';
  end if;

  v_new_status := 'refunded';
  update public.orders set status = v_new_status where id = p_order_id;
  return v_new_status;
exception when others then
  rollback;
  raise;
end;
$$ language plpgsql security definer;
