    and hm.role = 'parent'
    and household_id = chore.household_id
    and chore.assignee_id in (
      select user_id from public.household_members hm2
      join public.households h2 on h2.id = hm2.household_id
      where h2.id = h.id
      and hm2.role = 'child'
    )
    and chore.status = 'todo'
  )
);

