    select 1 from public.household_members hm
    join public.households h on h.id = hm.household_id
    where hm.user_id = auth.uid()
    and hm.role = 'parent'
    and h.id = chore.household_id
    and not public.is_chore_approved(chore.id)
  )
) with check (
  exists (
    select 1 from public.household_members hm
    join public.households h on h.id = hm.household_id
    where hm.user_id = auth.uid()
    and hm.role = 'parent'
    and h.id = chore.household_id
    and not public.is_chore_approved(chore.id)
  )
);

-- Delete
create policy "Parents can delete unapproved chores in their household" on public.chores for delete to authenticated using (
  exists (
    select 1 from public.household_members hm
    join public.households h on h.id = hm.household_id
    where hm.user_id = auth.uid()
    and hm.role = 'parent'
    and h.id = chore.household_id
    and not public.is_chore_approved(chore.id)
  )
);

-- Policy: R3 - Children can mark their own todo chores as done, and nothing else
-- Update (only allow updating status to 'done' for their own todo chores)
create policy "Children can update own todo chores to done" on public.chores for update to authenticated using (
  is_child(auth.uid())
  and assignee_id = auth.uid()
  and status = 'todo'
  and new.status = 'done'
) with check (
  is_child(auth.uid())
  and assignee_id = auth.uid()
  and status = 'todo'
  and new.status = 'done'
);

-- Policy: R4 - Parents can approve chores in their household
-- Update (allow changing status to 'approved')
create policy "Parents can approve chores in their household" on public.chores for update to authenticated using (
  exists (
    select 1 from public.household_members hm
    join public.households h on h.id = hm.household_id
    where hm.user_id = auth.uid()
    and hm.role = 'parent'
    and h.id = chore.household_id
    and status != 'approved'
  )
) with check (
  exists (
    select 1 from public.household_members hm
    join public.households h on h.id = hm.household_id
    where hm.user_id = auth.uid()
    and hm.role = 'parent'
    and h.id = chore.household_id
    and new.status = 'approved'
  )
);

-- Policy: R4 - Once a chore is approved, nobody can change or delete it.
-- We handle the "nobody can change" part via the update policies above which check `status != 'approved'`.
-- However, we need to explicitly prevent deletion of approved chores.
-- The previous delete policy only allowed deleting unapproved chores, so this is implicitly covered.
-- But let's be explicit that approved chores cannot be deleted by anyone else (except potentially service_role which we already gave full access).
-- Current delete policy restricts to unapproved. So approved chores are safe from delete by authenticated users.

-- Double check: Can a parent delete an approved chore?
-- The delete policy `using` clause requires `not public.is_chore_approved(chore.id)`.
-- If the chore is approved, `is_chore_approved` returns true, so `not true` is false.
-- Thus, the policy fails, and the delete is denied. This satisfies R4.

-- Ensure service role can still do everything (already defined above, but good to be clear)
-- No additional grants needed as service_role bypasses RLS.

-- Grant necessary permissions to authenticated users for the functions we created
-- These functions are SECURITY DEFINER, so they run as the owner (public schema owner or specific user).
-- We need to ensure the functions can access the tables. Since they are security definer, they don't need grants on the tables for the calls to work, 
-- but the calling user needs permissions on the functions.
grant execute on function public.is_parent(uuid) to authenticated;
grant execute on function public.get_user_households(uuid) to authenticated;
grant execute on function public.is_child(uuid) to authenticated;
grant execute on function public.get_user_household_members(uuid) to authenticated;
grant execute on function public.is_chore_approved(bigint) to authenticated;
grant execute on function public.is_chore_owner(uuid, bigint) to authenticated;
