  values (p_auction_id, auth.uid(), p_amount, now());

  -- Update the highest bid
  update public.auctions
  set highest_bid = p_amount
  where id = p_auction_id;

  -- Return the new highest bid
  return p_amount;
exception
  when others then
    -- Rollback any partial changes if an exception occurs before commit (handled by PL/pgSQL transaction scope)
    raise;
end;
$$;

