-- Enable RLS on tables
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

-- Helper function to get current auction details for policy evaluation
create or replace function public.get_auction_context()
returns table (
  auction_id bigint,
  ends_at timestamptz,
  highest_bid numeric,
  min_increment numeric
) language plpgsql security definer
as $$
begin
  return query select 
    a.id as auction_id,
    a.ends_at,
    a.highest_bid,
    a.min_increment
  from auctions a
  where a.id = current_setting('app.current_auction_id')::bigint;
end;
$$;

-- Helper function to update auction state after a bid
create or replace function public.update_auction_state(new_bid_amount numeric)
returns trigger
language plpgsql security definer
as $$
begin
  update auctions
  set highest_bid = new_bid_amount
  where id = coalesce(current_setting('app.current_auction_id')::bigint, new.auction_id);
  return new;
end;
$$;

-- Policy for Auctions: Read access
create policy "Users can read auctions" on public.auctions
  for select
  using (true);

-- Policy for Bids: Read access
create policy "Users can read own bids and sellers can read all bids" on public.bids
  for select
  using (
    auth.jwt()->>'role' = 'seller' 
    OR (auth.uid() = bidder_id)
  );

-- Function to validate bid logic (R4, R5)
create or replace function public.validate_bid(p_auction_id bigint, p_amount numeric)
returns boolean
language plpgsql
security definer
as $$
declare
  v_auction auctions;
  v_min_increment numeric;
  v_highest_bid numeric;
  v_starts_price numeric;
  v_bidder_id uuid;
  v_ends_at timestamptz;
begin
  -- Check if signed in (R5)
  if auth.jwt() is null or auth.jwt() is not null and auth.jwt()->>'role' is null then
    return false;
  end if;

  -- Get auction details
  select * into v_auction
  from auctions
  where id = p_auction_id;

  if not found then
    return false;
  end if;

  v_min_increment := v_auction.min_increment;
  v_highest_bid := coalesce(v_auction.highest_bid, 0);
  v_starts_price := v_auction.starting_price;
  v_ends_at := v_auction.ends_at;
  v_bidder_id := auth.uid();

  -- Check if auction is active (R3)
  if now() > v_ends_at then
    return false;
  end if;

  -- Check if caller is the seller (R4)
  if v_bidder_id = v_auction.seller_id then
    return false;
  end if;

  -- Check minimum amount (R4)
  if p_amount <= v_starts_price then
    return false;
  end if;

  if p_amount <= v_highest_bid + v_min_increment then
    return false;
  end if;

  return true;
end;
$$;

-- Trigger to set auction context for the RPC call
create trigger set_auction_context_trigger
before execute on public.place_bid
  for each statement
  execute function public.set_auction_context_trigger();

-- Create the place_bid RPC function with strict access control
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
as $$
declare
  v_new_highest_bid numeric;
  v_bid_record bids;
begin
  -- Validate the bid first
  if not public.validate_bid(p_auction_id, p_amount) then
    raise exception 'Invalid bid';
  end if;

  -- Insert the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now())
  returning * into v_bid_record;

  -- Update the auction's highest bid
  update public.auctions
  set highest_bid = p_amount
  where id = p_auction_id;

  return p_amount;
end;
$$;

-- Grant service role full access for internal operations (R6)
grant all on public.auctions to service_role;
grant all on public.bids to service_role;
grant all on function public.place_bid to service_role;
grant all on function public.update_auction_state to service_role;
grant all on function public.validate_bid to service_role;
grant all on function public.get_auction_context to service_role;
