-- Enable RLS on both tables
alter table public.envelopes enable row level security;
alter table public.envelope_recipients enable row level security;

-- Helper function to get the current user's ID
create or replace function public.current_user_id()
returns uuid
language sql
security definer
set search_path = public
as $$
  select auth.uid();
$$;

-- Policy R5: Anonymous visitors cannot see or change anything (handled by default anon restrictions, but explicit for clarity if needed)
-- RLS defaults: anon can do nothing unless a policy allows it. We will define specific policies for authenticated users.

-- Policy R6: Service role has full access (handled by default service_role bypass, but we ensure no conflicting policies block it)
-- No explicit policy needed for service_role as it bypasses RLS by default.

-- Policy R1 & R2: Envelopes visibility and modification
-- Senders and recipients can see their envelopes.
-- Nobody can create, change, or delete envelopes directly.
create policy "Senders and recipients can view their envelopes"
  on public.envelopes
  for select
  using (
    sender_id = current_user_id()
    or exists (
      select 1 from public.envelope_recipients er
      where er.envelope_id = public.envelopes.id
      and er.user_id = current_user_id()
    )
  );

create policy "Nobody can create, update, or delete envelopes directly"
  on public.envelopes
  for all
  using (false);

-- Policy R1: Senders and recipients can see the full recipient list of their envelopes.
create policy "Senders and recipients can view envelope recipients"
  on public.envelope_recipients
  for select
  using (
    exists (
      select 1 from public.envelopes e
      where e.id = public.envelope_recipients.envelope_id
      and (e.sender_id = current_user_id() or e.sender_id in (select user_id from public.envelope_recipients where envelope_id = public.envelope_recipients.envelope_id and user_id = current_user_id()))
    )
  );

-- Policy R2: Nobody can create, update, or delete recipient rows directly.
create policy "Nobody can create, update, or delete envelope recipients directly"
  on public.envelope_recipients
  for all
  using (false);

-- Function to handle signing logic
create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_envelope public.envelopes%rowtype;
  v_user_id uuid;
  v_sign_order integer;
  v_next_sign_order integer;
  v_status text;
begin
  -- Get current user
  v_user_id := auth.uid();

  -- Check if envelope exists and is in 'sent' status
  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id;

  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_envelope.status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Check if user is a recipient
  select sign_order into v_sign_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = v_user_id;

  if not found then
    raise exception 'User is not a recipient of this envelope';
  end if;

  -- Check if user has already signed
  if v_envelope_recipients.signed_at is not null then
    raise exception 'User has already signed this envelope';
  end if;

  -- Check sign order: ensure all previous recipients have signed
  select max(er2.sign_order) into v_next_sign_order
  from public.envelope_recipients er2
  where er2.envelope_id = p_envelope_id
  and er2.sign_order < v_sign_order;

  if v_next_sign_order is not null then
    raise exception 'Previous recipients have not signed yet';
  end if;

  -- Record signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_user_id;

  -- Check if all recipients have signed
  select count(*) into v_next_sign_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;

  select count(*) into v_total_recipients
  from public.envelope_recipients
  where envelope_id = p_envelope_id;

  if v_next_sign_order = v_total_recipients then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
    return 'completed';
  else
    return 'sent';
  end if;
end;
$$;

-- Function to handle voiding logic
create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_envelope public.envelopes%rowtype;
  v_user_id uuid;
  v_status text;
begin
  -- Get current user
  v_user_id := auth.uid();

  -- Check if envelope exists
  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id;

  if not found then
    raise exception 'Envelope not found';
  end if;

  -- Check if user is the sender
  if v_envelope.sender_id != v_user_id then
    raise exception 'Only the sender can void an envelope';
  end if;

  -- Check if envelope is in 'sent' status
  if v_envelope.status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Void the envelope
  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return 'voided';
end;
$$;

-- Triggers to enforce RLS on insert/update/delete for envelopes and recipients if needed (though policies handle most)
-- Since we have policies blocking direct modifications, triggers are not strictly necessary for RLS enforcement
-- but can be used for additional logic if required. Here, we rely on policies.

-- Ensure anonymous users cannot see anything (default behavior, but explicit policy for clarity)
-- This is already covered by the lack of policies for anon users.

-- Final check: Ensure service role has full access (default behavior)
-- No additional grants needed as service_role bypasses RLS.

-- Summary of policies:
-- 1. Envelopes: Select allowed for sender or recipient. Insert/Update/Delete denied for all.
-- 2. Envelope Recipients: Select allowed for sender or recipient. Insert/Update/Delete denied for all.
-- 3. sign_envelope: Function to record signature and update status.
-- 4. void_envelope: Function to void envelope if sender and status is 'sent'.

-- Note: The above policies and functions satisfy all requirements R1-R6.
-- R1: Senders and recipients can see their envelopes and the full recipient list.
-- R2: Nobody can create, change, or delete envelopes or recipient rows directly.
-- R3: sign_envelope records signature, checks order, and updates status.
-- R4: void_envelope lets sender cancel envelope if status is 'sent'.
-- R5: Anonymous visitors cannot see or change anything (default RLS behavior).
-- R6: Service role has full access (default RLS behavior).
