-- RPC sign_envelope
create or replace function public.sign_envelope(p_envelope_id bigint)
returns text as $$
declare
  v_user_id uuid;
  v_next_order integer;
  v_status text;
begin
  -- Get current user
  v_user_id := public.current_user_id();

  -- Check if user is the next signer
  if not public.is_next_signer(p_envelope_id) then
    raise foreign_key_violation using message = 'Error: You are not the next signer in line or not a recipient.';
  end if;

  -- Check if envelope is not sent
  select status into v_status
  from public.envelopes
  where id = p_envelope_id;

  if v_status is null or v_status != 'sent' then
    raise foreign_key_violation using message = 'Error: Envelope is not in "sent" status.';
  end if;

  -- Record the signature
  insert into public.envelope_recipients (envelope_id, user_id, sign_order, signed_at)
  values (p_envelope_id, v_user_id, (select sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id), now());

  -- Check if all recipients have signed to complete the envelope
  if public.has_previous_signers_signed(p_envelope_id) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
  end if;

  return v_status;
end;
$$ language plpgsql security definer;

-- RPC void_envelope
create or replace function public.void_envelope(p_envelope_id bigint)
returns text as $$
declare
  v_user_id uuid;
  v_status text;
  v_sender_id uuid;
begin
  -- Get current user
  v_user_id := public.current_user_id();

  -- Check if user is the sender
  if not public.is_sender(p_envelope_id) then
    raise foreign_key_violation using message = 'Error: Only the sender can void an envelope.';
  end if;

  -- Get sender ID from envelope
  select sender_id into v_sender_id
  from public.envelopes
  where id = p_envelope_id;

  if v_sender_id is null or v_sender_id != v_user_id then
    raise foreign_key_violation using message = 'Error: You are not the sender of this envelope.';
  end if;

  -- Check if envelope is sent
  select status into v_status
  from public.envelopes
  where id = p_envelope_id;

  if v_status is null or v_status != 'sent' then
    raise foreign_key_violation using message = 'Error: Can only void envelopes with status "sent".';
  end if;

  -- Void the envelope
  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return v_status;
end;
$$ language plpgsql security definer;

