-- Function to sign an envelope
create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security invoker
set search_path = public
as $$
begin
  -- Check if envelope exists
  if not exists (select 1 from public.envelopes where id = p_envelope_id) then
    raise exception 'Envelope not found';
  end if;

  -- Check if user is a recipient
  if not public.is_recipient(p_envelope_id) then
    raise exception 'Not a recipient of this envelope';
  end if;

  -- Check if user has already signed
  if exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and user_id = public.current_user_id() and signed_at is not null
  ) then
    raise exception 'You have already signed this envelope';
  end if;

  -- Check if envelope is still 'sent'
  if (select status from public.envelopes where id = p_envelope_id) != 'sent' then
    raise exception 'Envelope is not in "sent" status';
  end if;

  -- Check if previous signers have signed
  if not public.all_previous_signed(p_envelope_id, public.current_user_id()) then
    raise exception 'Previous signers have not signed yet';
  end if;

  -- Insert the signature
  insert into public.envelope_recipients (envelope_id, user_id, sign_order, signed_at)
  values (p_envelope_id, public.current_user_id(), null, now());

  -- Update status to completed if all recipients have signed
  -- We need to count total recipients vs signed recipients for this envelope
  declare
    total_count integer;
    signed_count integer;
  begin
    select count(*) into total_count from public.envelope_recipients where envelope_id = p_envelope_id;
    select count(*) into signed_count from public.envelope_recipients where envelope_id = p_envelope_id and signed_at is not null;

    if signed_count = total_count then
      update public.envelopes set status = 'completed' where id = p_envelope_id;
    end if;
  end;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

