-- Policy R3: sign_envelope RPC logic (handled by trigger)
-- We create a trigger to enforce the business logic of signing.
create function public.sign_envelope_trigger()
returns trigger as $$
declare
  v_status text;
  v_order integer;
  v_prev_max_order integer;
  v_all_signed boolean;
begin
  -- Check if caller is a recipient
  if not public.is_recipient(NEW.envelope_id) then
    raise exception 'User is not a recipient of this envelope';
  end if;

  -- Check if envelope is 'sent'
  select status into v_status from public.envelopes where id = NEW.envelope_id;
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Get current user's order
  select sign_order into v_order
  from public.envelope_recipients
  where envelope_id = NEW.envelope_id and user_id = auth.uid();

  -- Check if user has already signed
  if NEW.signed_at is not null then
    raise exception 'User has already signed this envelope';
  end if;

  -- Check if all previous signers have signed
  select max(sign_order) into v_prev_max_order
  from public.envelope_recipients
  where envelope_id = NEW.envelope_id and user_id != auth.uid();

  if v_prev_max_order is not null and v_prev_max_order >= v_order then
    raise exception 'Not all previous signers have signed yet';
  end if;

  -- Update the record
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = NEW.envelope_id and user_id = auth.uid();

  -- Check if all recipients have signed to update envelope status
  select count(*) = (select count(*) from public.envelope_recipients where envelope_id = NEW.envelope_id)
  into v_all_signed
  from public.envelope_recipients
  where envelope_id = NEW.envelope_id and signed_at is not null;

  if v_all_signed then
    update public.envelopes
    set status = 'completed'
    where id = NEW.envelope_id;
  end if;

  return NEW;
end;
