-- RPC: sign_envelope
create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_envelope_status text;
  v_user_signed_at timestamptz;
  v_recipient_record public.envelope_recipients;
begin
  -- Get current user
  select auth.uid() into v_user_id;

  -- Check if user is authenticated (R5)
  if v_user_id is null then
    raise exception 'User must be authenticated to sign';
  end if;

  -- Check if user is a recipient of this envelope
  if not exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id) then
    raise exception 'User is not a recipient of this envelope';
  end if;

  -- Check if user has already signed
  if exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id and signed_at is not null) then
    raise exception 'User has already signed this envelope';
  end if;

  -- Check if envelope is still 'sent'
  select status into v_envelope_status from public.envelopes where id = p_envelope_id;
  if v_envelope_status != 'sent' then
    raise exception 'Envelope is not in "sent" status';
  end if;

  -- Check if previous signers have signed
  if exists (
    select 1 from public.envelope_recipients prev
    where prev.envelope_id = p_envelope_id 
    and prev.user_id = v_user_id
    and prev.sign_order < (select sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id)
    and prev.signed_at is null
  ) then
    raise exception 'Previous recipients have not signed yet';
  end if;

  -- Insert the signature
  insert into public.envelope_recipients (envelope_id, user_id, sign_order, signed_at)
  select 
    p_envelope_id,
    v_user_id,
    (select sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id),
    now()
  where exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id); -- Ensure record exists before updating timestamp/order if needed, though insert should use the existing row if we update.

  -- Actually, we need to UPDATE the existing row to set signed_at.
  -- Let's refine the logic: find the row, check constraints, then update.

  -- Re-fetch to ensure we have the latest state for ordering check
  select * into v_recipient_record 
  from public.envelope_recipients 
  where envelope_id = p_envelope_id and user_id = v_user_id;

  if v_recipient_record.sign_order IS NULL then
     -- Handle case where sign_order might not be set in row (shouldn't happen based on schema, but safe guard)
     -- Assuming sign_order is set when recipient is added.
     raise exception 'Sign order not found for recipient';
  end if;

  -- Update the signed_at
  update public.envelope_recipients 
  set signed_at = now() 
  where id = v_recipient_record.id;

  -- Check if all recipients have signed
  if public.all_recipients_signed(p_envelope_id) then
    update public.envelopes 
    set status = 'completed' 
    where id = p_envelope_id;
  end if;

  return (select status from public.envelopes where id = p_envelope_id);
exception
  when others then
    -- Rollback any partial changes if error occurs (though standard SQL handles this)
    raise;
end;
$$;

-- RPC: void_envelope
create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_envelope_status text;
  v_sender_id uuid;
begin
  -- Get current user
  select auth.uid() into v_user_id;

  if v_user_id is null then
    raise exception 'User must be authenticated to void';
  end if;

  -- Check if user is the sender
  select sender_id into v_sender_id from public.envelopes where id = p_envelope_id;
  if v_sender_id != v_user_id then
    raise exception 'Only the sender can void an envelope';
  end if;

  -- Check if envelope is still 'sent'
  select status into v_envelope_status from public.envelopes where id = p_envelope_id;
  if v_envelope_status != 'sent' then
    raise exception 'Envelope is not in "sent" status';
  end if;

  -- Update status
  update public.envelopes 
  set status = 'voided' 
  where id = p_envelope_id;

  return 'voided';
exception
  when others then
    raise;
end;
$$;

