language plpgsql
as $$
declare
  v_user_id uuid := auth.uid();
  v_status text;
  v_next_order integer;
  v_current_order integer;
  v_signed_at timestamptz;
begin
  -- Check if envelope exists and is sent
  select status into v_status from public.envelopes where id = p_envelope_id;
  if v_status is null then
    raise exception 'Envelope not found';
  end if;

  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status. Current status: %', v_status;
  end if;

  -- Check if user is a recipient
  if not exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id) then
    raise exception 'User is not a recipient of this envelope';
  end if;

  -- Check if user has already signed
  if exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id and signed_at is not null) then
    raise exception 'User has already signed this envelope';
  end if;

  -- Get current sign order for this user
  select sign_order into v_current_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id;

  -- Check if earlier recipients have signed
  if not exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
    and r.sign_order < v_current_order
    and r.signed_at is not null
  ) then
    raise exception 'Previous recipients have not signed yet';
  end if;

  -- Record signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_user_id;

  -- Check if all recipients have signed
  if public.all_recipients_signed(p_envelope_id) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
    return 'completed';
  else
    return 'sent';
  end if;
end;
$$;

