create or replace function public._is_share_valid(item_id bigint, target_tenant text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  return exists (
    select 1
    from public.item_shares
    where item_id = item_id
      and target_tenant = target_tenant
      and (expires_at is null or expires_at > now())
  );
end;
$$;

-- Helper function to check if current user's tenant is the target of a share
create or replace function public._is_target_of_share(item_id bigint)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  current_tenant text;
begin
  select jwt->>'app_metadata'->>'tenant_id' into current_tenant
  from auth.jwt();

  return current_tenant is not null
    and exists (
      select 1
      from public.item_shares
      where item_id = item_id
        and target_tenant = current_tenant
        and (expires_at is null or expires_at > now())
    );
end;
$$;

-- Policy R1: Users can see their own tenant's items, plus items shared with their tenant.
create policy "Users can view their own tenant's items and shared items"
  on public.items
  for select
  using (
    (select tenant_id from public._check_auth_context()) = tenant_id
    or _is_target_of_share(id)
  );

-- Policy R2: Only admins can create, edit, delete items. Tenants can read (covered by R1).
create policy "Admins can manage their tenant's items"
  on public.items
  for all
  using (_is_tenant_admin())
  with check (
    (select tenant_id from public._check_auth_context()) = tenant_id
    or _is_tenant_admin() -- Ensure even if read access granted via share, write requires admin
  );

-- Policy R3: Only admins of the owning tenant can manage shares.
-- Note: Users cannot insert shares for other tenants' items due to tenant_id check in using clause below.
create policy "Admins can manage their tenant's item shares"
  on public.item_shares
  for all
  using (
    exists (
      select 1
      from public.items i
      where i.id = item_shares.item_id
        and i.tenant_id = (select tenant_id from public._check_auth_context())
        and (select tenant_id from public._check_auth_context()) = (select tenant_id from public._check_auth_context()) -- Redundant but explicit
    )
    and _is_tenant_admin()
  )
  with check (
    exists (
      select 1
      from public.items i
      where i.id = item_shares.item_id
        and i.tenant_id = (select tenant_id from public._check_auth_context())
    )
  );

-- Policy R4: Users can see shares of their own tenant's items and shares addressed to their tenant.
create policy "Users can view relevant item shares"
  on public.item_shares
  for select
  using (
    exists (
      select 1
      from public.items i
      where i.id = item_shares.item_id
        and i.tenant_id = (select tenant_id from public._check_auth_context())
    )
    or exists (
      select 1
      from public.items i
      where i.id = item_shares.item_id
        and i.tenant_id != (select tenant_id from public._check_auth_context())
        and item_shares.target_tenant = (select tenant_id from public._check_auth_context())
        and (item_shares.expires_at is null or item_shares.expires_at > now())
    )
  );

-- Grant full access to service_role
grant all on public.items to service_role;
grant all on public.item_shares to service_role;

-- Revoke all from anon to ensure no access without proper JWT (handled by policies, but explicit revoke for safety on tables)
revoke all on public.items from anon;
revoke all on public.item_shares from anon;
revoke all on public.items from authenticated;
revoke all on public.item_shares from authenticated;
