-- Enable RLS on both tables
alter table public.items enable row level security;
alter table public.item_shares enable row level security;

-- Helper function to extract tenant and role from JWT
create or replace function public._check_auth_context()
returns record as $$
begin
  return row(
    auth.jwt() ->>'app_metadata' ->>'tenant_id',
    auth.jwt() ->>'app_metadata' ->>'role'
  );
end;
$$ language plpgsql security definer;

-- RLS Policies for public.items

-- R5: Anonymous users cannot see anything
create policy "Anonymous users cannot see anything" on public.items
for select using (false);

-- R1, R2, R5: Users can see their own tenant's items, plus shared items (not expired)
create policy "Users see own items and valid shares" on public.items
for select
using (
  exists (
    select 1 from public.item_shares sh
    where sh.item_id = public.items.id
    and sh.target_tenant = public._check_auth_context().tenant_id
    and (sh.expires_at is null or sh.expires_at > now())
  )
  or public.items.tenant_id = public._check_auth_context().tenant_id
);

-- R2, R5: Only admins can create, update, delete their tenant's items
create policy "Admins can manage tenant items" on public.items
for all
using (
  public.items.tenant_id = public._check_auth_context().tenant_id
  and public._check_auth_context().role = 'admin'
);

-- R2, R3, R5: Only admins of the owning tenant can manage shares
create policy "Admins manage item shares" on public.item_shares
for all
using (
  exists (
    select 1 from public.items i
    where i.id = public.item_shares.item_id
    and i.tenant_id = public._check_auth_context().tenant_id
    and public._check_auth_context().role = 'admin'
  )
);

-- R4, R5: Users can see shares of their own tenant's items and shares addressed to their tenant
create policy "Users see relevant shares" on public.item_shares
for select
using (
  -- Shares belonging to the user's tenant
  exists (
    select 1 from public.items i
    where i.id = public.item_shares.item_id
    and i.tenant_id = public._check_auth_context().tenant_id
  )
  or
  -- Shares addressed to the user's tenant
  public.item_shares.target_tenant = public._check_auth_context().tenant_id
);

-- R6: Service role bypasses RLS
revoke all on public.items from authenticated, anon;
revoke all on public.item_shares from authenticated, anon;
grant all on public.items to service_role;
grant all on public.item_shares to service_role;
