-- Enable Row Level Security on board_notes
ALTER TABLE public.board_notes ENABLE ROW LEVEL SECURITY;

-- Drop existing policies if any (to ensure clean state for this schema)
DROP POLICY IF EXISTS "Anyone can read all notes" ON public.board_notes;
DROP POLICY IF EXISTS "Authenticated users can insert their own notes" ON public.board_notes;
DROP POLICY IF EXISTS "Users can update their own notes" ON public.board_notes;
DROP POLICY IF EXISTS "Users can delete their own notes" ON public.board_notes;
DROP POLICY IF EXISTS "Moderators can pin/unpin notes" ON public.board_notes;
DROP POLICY IF EXISTS "Service role has full access" ON public.board_notes;

-- Policy R1: Anyone can read all notes
CREATE POLICY "Anyone can read all notes"
ON public.board_notes
FOR SELECT
USING (true);

-- Policy R4 & R2: Anonymous cannot post; Authenticated can post their own
CREATE POLICY "Authenticated users can insert their own notes"
ON public.board_notes
FOR INSERT
WITH CHECK (auth.uid() = author_id);

-- Policy R2: Users can update their own notes (non-pinned fields)
CREATE POLICY "Users can update their own notes"
ON public.board_notes
FOR UPDATE
USING (auth.uid() = author_id)
WITH CHECK (auth.uid() = author_id);

-- Policy R3 & R5: Moderators (via service_role usually, but handled here by role check or service role bypass) can pin/unpin.
-- Since R3 says "Only moderators pin", and R5 says service role has full access, we create a policy for the 'moderator' role.
-- If the application uses the service_role for pinning (as per "admin tool that uses the service role"), this policy might be redundant for the service role but necessary for standard authenticated moderators if they exist.
-- However, R5 explicitly states service role bypasses RLS. So we only need a policy for the 'moderator' role if such users exist in auth.users.
-- Assuming 'moderator' is a role assigned to users in auth.users.
CREATE POLICY "Moderators can pin and unpin notes"
ON public.board_notes
FOR UPDATE
USING (auth.role() = 'moderator')
WITH CHECK (auth.role() = 'moderator');

-- Policy R5: Service role has full access (bypasses RLS)
-- Note: By default, service_role bypasses RLS in Supabase. However, explicitly creating a policy or ensuring grants are correct is good practice.
-- Since service_role bypasses RLS, no INSERT/UPDATE/DELETE policy is strictly needed for it to work, but we can grant full access to be explicit if RLS was somehow interfering in a custom setup, though standard Supabase behavior handles this.
-- To strictly follow "Service role keeps full access", we ensure the role has permissions that override or are recognized.
-- In Supabase, service_role automatically bypasses RLS. We do not need a policy for it.
-- We do need to ensure the table is accessible.

-- Grant necessary permissions to roles
GRANT SELECT ON public.board_notes TO authenticated;
GRANT INSERT, SELECT, UPDATE, DELETE ON public.board_notes TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.board_notes TO moderator;
GRANT ALL ON public.board_notes TO service_role;

-- Revoke permissions from anon to enforce R4 (Anonymous cannot post/change)
REVOKE INSERT, UPDATE, DELETE ON public.board_notes FROM anon;
-- SELECT is implicitly allowed or needs explicit grant if anon doesn't have it by default.
-- R1 says "Anyone... can read", so we must grant SELECT to anon.
GRANT SELECT ON public.board_notes TO anon;
