$$;

-- Trigger to prevent deletion of jobs (R5)
create or replace function public.prevent_job_deletion()
returns trigger
security definer
set search_path = public
language plpgsql
as $$
begin
  if (tg_op = 'DELETE') then
    raise exception 'Jobs cannot be deleted';
  end if;
  return null;
end;
$$;

create trigger on_job_delete_trigger
before delete on public.jobs
for each row
execute procedure public.prevent_job_deletion();

-- Trigger to prevent updates to garage_id or mechanics references (R5)
create or replace function public.prevent_garage_mechanic_changes()
returns trigger
security definer
set search_path = public
language plpgsql
as $$
begin
  if (tg_op = 'UPDATE') then
    if (tg_table = 'public.garages') then
      raise exception 'Garages cannot be modified through the app';
    end if;
    if (tg_table = 'public.mechanics') then
      raise exception 'Mechanics cannot be modified through the app';
    end if;
    -- Check jobs update for forbidden columns
    if (tg_table = 'public.jobs') then
      if (tg_col::text = 'garage_id' or tg_col::text = 'customer_id') then
        raise exception 'Garage and customer cannot be changed for a job';
      end if;
    end if;
  end if;
  return null;
end;
$$;

