create policy "Mechanics can open jobs for their garage" on public.jobs
for insert
with check (
  auth.jwt() is not null
  and auth.role() != 'service_role'
  and exists (
    select 1 from public.mechanics m
    where m.user_id = auth.uid()
    and m.garage_id = new.garage_id
  )
  and new.status = 'quoted'
);

-- Policy: Mechanics update jobs (R2, R4)
create policy "Mechanics can update jobs for their garage" on public.jobs
for update
using (
  auth.jwt() is not null
  and auth.role() != 'service_role'
  and exists (
    select 1 from public.mechanics m
    where m.user_id = auth.uid()
    and m.garage_id = old.garage_id
  )
  and (
    -- Can only change status if it's quoted -> in_progress or in_progress -> done
    (old.status = 'quoted' and new.status in ('quoted', 'in_progress'))
    or (old.status = 'in_progress' and new.status = 'done')
    -- Can update anything else if status is quoted (R2: change quote)
    or (old.status = 'quoted' and new.status = 'quoted')
  )
  -- Ensure quote_amount is never changed after approval
  and (old.status != 'approved' or old.quote_amount = new.quote_amount)
  -- Ensure quote_amount is never changed to null or something else if it was set
  and (old.status = 'quoted' or new.status != 'quoted')
);

-- Policy: Customers can see their own jobs (R1)
create policy "Customers can see their own jobs" on public.jobs
for select
using (
  auth.jwt() is not null
  and old.customer_id = auth.uid()
);

-- Policy: Mechanics can see every job of their garage (R1)
