for select
using (
  auth.jwt() is not null
  and auth.role() != 'service_role'
  and exists (
    select 1 from public.mechanics m
    where m.user_id = auth.uid()
    and m.garage_id = old.garage_id
  )
);

-- Policy: Only customer can approve (update status to approved) (R3)
create policy "Only the job's customer can approve a quoted job" on public.jobs
for update
using (
  auth.jwt() is not null
  and auth.role() != 'service_role'
  and old.customer_id = auth.uid()
  and old.status = 'quoted'
  and new.status = 'approved'
  -- R3: approving cannot change anything else
  and new.quote_amount = old.quote_amount
  and new.vehicle = old.vehicle
  and new.status = 'approved'
);

-- Policy: Mechanics cannot approve (R4)
create policy "Mechanics cannot approve jobs" on public.jobs
for update
using (
  auth.jwt() is not null
  and auth.role() != 'service_role'
  and old.status != 'quoted' or not exists (
    select 1 from public.mechanics m
    where m.user_id = auth.uid()
    and m.garage_id = old.garage_id
  )
);

-- Policy: Mechanics can move approved jobs to in_progress or done (R4)
create policy "Mechanics can move approved jobs to in_progress or done" on public.jobs
for update
using (
  auth.jwt() is not null
  and auth.role() != 'service_role'
  and exists (
    select 1 from public.mechanics m
    where m.user_id = auth.uid()
    and m.garage_id = old.garage_id
  )
  and (
    (old.status = 'approved' and new.status = 'in_progress')
    or (old.status = 'in_progress' and new.status = 'done')
  )
  -- R4: without changing the quote
  and new.quote_amount = old.quote_amount
  and new.vehicle = old.vehicle
);

-- Policy: Anonymous users cannot see or change anything (R6)
-- This is implicitly handled by most policies requiring auth.jwt() is not null.
-- However, to be explicit for any policy that might be missing auth check (like garage insert if needed later),
-- we rely on the existing checks. For completeness, we ensure no implicit access.
-- The current setup already blocks anonymous via `auth.jwt() is not null`.

-- Grants for service role (R7)
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant all on all triggers in schema public to service_role;
grant all on all views in schema public to service_role;

-- Revoke public access if any (explicit deny for anonymous)
revoke all on public.garages from anon;
revoke all on public.mechanics from anon;
revoke all on public.jobs from anon;
