-- Enable RLS on both tables
alter table public.household_members enable row level security;
alter table public.shopping_items enable row level security;

-- Helper function to get the current user's household IDs
create or replace function public.get_user_household_ids()
returns bigint[]
language sql
stable
security definer
set search_path = public
as $$
  select array_agg(hm.household_id)
  from public.household_members hm
  where hm.user_id = auth.uid();
$$;

-- Policy R1: Members can see their household's members and all of its items
create policy "Members can view their household members"
  on public.household_members
  for select
  using (
    auth.role() = 'service_role'
    or auth.uid() = user_id
    or household_id = any((select get_user_household_ids()))
  );

create policy "Members can view their household shopping items"
  on public.shopping_items
  for select
  using (
    auth.role() = 'service_role'
    or household_id = any((select get_user_household_ids()))
  );

-- Policy R2: Members can add items to their household as themselves
create policy "Members can add items to their household"
  on public.shopping_items
  for insert
  with check (
    auth.role() = 'service_role'
    or (
      household_id = any((select get_user_household_ids()))
      and auth.uid() = added_by
      and claimed_by is null
      and is_bought = false
    )
  );

-- Policy R3: Members can claim/unclaim items they own or are in the household
create policy "Members can claim or unclaim items"
  on public.shopping_items
  for update
  using (
    auth.role() = 'service_role'
    or (
      household_id = any((select get_user_household_ids()))
      and (
        -- Can claim if unclaimed and belongs to household
        (claimed_by is null and auth.uid() = auth.uid())
        -- Can unclaim only if they claimed it
        or (claimed_by = auth.uid() and auth.uid() = auth.uid())
      )
    )
  );

-- Policy R4: Only the member who claimed an item can mark it bought
create policy "Only claimer can mark item bought"
  on public.shopping_items
  for update
  using (
    auth.role() = 'service_role'
    or (
      household_id = any((select get_user_household_ids()))
      and claimed_by = auth.uid()
    )
  );

-- Policy R5: The member who added an item can delete it while it is not bought
create policy "Adder can delete unbought items"
  on public.shopping_items
  for delete
  using (
    auth.role() = 'service_role'
    or (
      household_id = any((select get_user_household_ids()))
      and added_by = auth.uid()
      and is_bought = false
    )
  );

-- Policy R6: Anonymous visitors cannot see or change anything (Implicitly handled by requiring auth.uid() in policies, but explicit deny for anon on sensitive ops if needed. However, standard Supabase RLS blocks anon if no policy matches. The policies above require auth.uid() checks which fail for anon. We ensure service_role bypasses everything.)
-- Explicitly ensure anon cannot do anything (default behavior if no policy matches, but let's be explicit for clarity on the 'cannot see' part if select policies didn't cover anon)
-- The select policies above require auth.uid() to be in a household. Anon has no user_id, so get_user_household_ids() returns null, and the check fails.
-- The insert/update/delete policies also require auth.uid() checks.
-- Thus, anon is blocked by default.

-- Grant service_role full access to bypass RLS for backend operations
grant all on public.household_members to service_role;
grant all on public.shopping_items to service_role;
