for all
using (auth.role() = 'authenticated');

-- Policy R5: restore_record logic is enforced via the function itself, but we need to ensure the function can only be called by admins of the org.
-- The function will handle the logic. We need to grant execute on the function to authenticated users, but the function body will check permissions.
-- However, to strictly follow "Nobody can create... audit rows directly through the app" except via the RPC, we rely on the trigger.
-- The RPC function needs to be able to update records.
-- We create the RPC function.

create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
security definer -- Ensures the function runs with the privileges of the caller, but we need to check caller is admin.
as $$
begin
  -- Check if record exists and is deleted
  if not exists (select 1 from public.records where id = p_record_id) then
    raise exception 'Record not found';
  end if;

  update public.records
  set deleted_at = null
  where id = p_record_id;

  -- Note: The requirement says "raise an error and change nothing unless...".
  -- The update above changes it. We need to check conditions BEFORE updating.
  -- Re-implementing logic to check first.
  rollback;

  -- Re-check conditions
  declare
    v_record deleted_at timestamptz;
    v_org_id bigint;
    v_is_admin boolean;
  begin
    select deleted_at, org_id into v_record, v_org_id
    from public.records
    where id = p_record_id;

    if v_record is not null then
      -- Record is deleted
      -- Check if deleted within last 30 days
      if v_record < now() - interval '30 days' then
        raise exception 'Record was deleted more than 30 days ago and cannot be restored';
      end if;

      -- Check if user is admin of the org
      select is_org_admin(v_org_id, auth.uid()) into v_is_admin;
      if not v_is_admin then
        raise exception 'Only admins can restore records';
      end if;

      -- All checks passed, perform update
      update public.records
      set deleted_at = null
      where id = p_record_id;
    else
      raise exception 'Record is not deleted';
    end if;
  end;
end;
$$;

-- Grant execute on the restore_record function to authenticated users (admins will be authenticated)
grant execute on function public.restore_record(bigint) to authenticated;

-- Trigger to handle R3: Insert/Update audit log
create or replace function public.handle_record_changes()
returns trigger
language plpgsql
as $$
begin
  insert into public.audit_log (record_id, action, actor)
  values (new.id, 'insert', auth.uid());
  return new;
end;
$$;

create trigger on_record_insert
after insert on public.records
for each row
execute function public.handle_record_changes();

