-- R3: Helper to log actions securely
create or replace function public.log_record_action(
  p_record_id bigint,
  p_action text
)
returns void
language plpgsql
security definer -- Runs with privileges of the function owner (needed to insert into audit_log if RLS blocks it, 
                  -- but here we rely on the fact that we are the 'service_role' caller or ensuring the function 
                  -- bypasses RLS on audit_log. However, the prompt says "Nobody can create... directly through the app".
                  -- If we use security definer, the function itself must be trusted. 
                  -- To strictly follow "Nobody can create... through the app", we might need a trigger that enforces this.
                  -- But the requirement is to add the row when insert/update happens.
                  -- We will create a trigger that calls this function.
                  -- Since the function is security definer, it bypasses RLS on the audit_log table, 
                  -- allowing it to insert regardless of the "block_audit_insert" policy which is for direct user access.
                  -- Wait, if the policy blocks insert for user, and the trigger calls the function, 
                  -- does the function bypass the policy? Yes, security definer functions bypass RLS on the table they access 
                  -- ONLY if they are run in a context where RLS is enforced? 
                  -- Actually, security definer functions run as the owner (usually postgres or the role that created them). 
                  -- They bypass RLS checks of the caller. So a trigger calling a security definer function will insert 
                  -- even if the user has 'block_audit_insert'. This satisfies R3.
as $$
begin
  insert into public.audit_log (record_id, action, actor)
  values (p_record_id, p_action, auth.uid());
end;
$$;

