create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
security definer -- Allows the function to check org_members and modify records without RLS blocking the admin check
as $$
declare
  v_org_id bigint;
  v_user_id uuid;
  v_role text;
  v_deleted_at timestamptz;
  v_days_since_delete int;
begin
  -- Get record details and org info
  select r.org_id, r.deleted_at
  into v_org_id, v_deleted_at
  from public.records r
  where r.id = p_record_id;

  if not found then
    raise exception 'Record not found';
  end if;

  -- Check if record is deleted
  if v_deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  -- Check if deleted within 30 days
  if (now() - v_deleted_at) > interval '30 days' then
    raise exception 'Record was deleted more than 30 days ago';
  end if;

  -- Verify caller is admin
  select om.org_id, om.role
  into v_org_id, v_role
  from public.org_members om
  where om.org_id = v_org_id and om.user_id = auth.uid();

  if not found then
    raise exception 'User is not a member of the organization';
  end if;

  if v_role != 'admin' then
    raise exception 'Only admins can restore records';
  end if;

  -- Perform the restore (clear deleted_at)
  update public.records
  set deleted_at = null
  where id = p_record_id;

  -- Log the restore action
  perform public.log_record_action(p_record_id, 'restore');
end;
$$;

