create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
security definer
as $$
declare
  v_record public.records;
  v_org_id bigint;
  v_user_id uuid;
  v_role text;
  v_days_since_delete integer;
begin
  -- 1. Fetch record to check existence and deleted_at
  select * into v_record
  from public.records
  where id = p_record_id;

  if not found then
    raise exception 'Record not found';
  end if;

  -- 2. Check if deleted
  if v_record.deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  -- 3. Calculate days since delete
  v_days_since_delete = extract(epoch from (now() - v_record.deleted_at)) / 86400;
  if v_days_since_delete > 30 then
    raise exception 'Record was deleted more than 30 days ago';
  end if;

  -- 4. Find org and user
  select r.org_id, om.user_id, om.role
  into v_org_id, v_user_id, v_role
  from public.records r
  inner join public.org_members om on r.org_id = om.org_id
  where r.id = p_record_id;

  -- 5. Check if caller is admin of that org
  if auth.uid() != v_user_id then
    raise exception 'Unauthorized: You are not the admin of this organization';
  end if;

  -- 6. Perform update
  update public.records
  set deleted_at = null
  where id = p_record_id;

  -- Log the restoration (optional but good practice, though R3 says audit is auto-generated)
  -- Since we are in a function, we can rely on the trigger if we trigger an update, 
  -- but the trigger fires on table updates. 
  -- However, the requirement says "restore_record clears deleted_at". 
  -- If we update the table, the trigger will fire and log 'update'. This is acceptable.
  -- If we want to log specifically as 'restore', we would need a custom trigger logic or manual insert.
  -- Given R3 "Every insert and update... adds an audit_log row", an update resulting in 'update' action is compliant.
  -- If strict 'restore' action string is needed, we might need to bypass the trigger or modify logic.
  -- Assuming 'update' action is sufficient for the audit trail of a restoration operation.
end;
$$;

