-- Function to set member role with logic
create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text
language plpgsql
security bypass
as $$
begin
  -- Validate role
  if p_role not in ('owner', 'admin', 'member') then
    raise exception 'Invalid role';
  end if;

  -- Get caller's membership
  declare
    caller_org_id bigint;
    caller_role text;
  begin
    select om.org_id, om.role
    into caller_org_id, caller_role
    from public.org_members om
    where om.user_id = auth.uid();

    -- Raise error if caller has no org membership
    if not found then
      raise exception 'Caller is not a member of any organization';
    end if;

    -- Raise error if caller is not in the target organization
    if caller_org_id is null or caller_org_id != p_org_id then
      raise exception 'Caller is not a member of the target organization';
    end if;

    -- Raise error if caller is not owner or admin
    if caller_role not in ('owner', 'admin') then
      raise exception 'Caller must be an owner or admin to change roles';
    end if;

    -- Raise error if target is an owner
    if exists (
      select 1 from public.org_members om
      where om.org_id = p_org_id
        and om.user_id = p_user_id
        and om.role = 'owner'
    ) then
      raise exception 'Cannot change an owner''s role';
    end if;

    -- Raise error if target is outside the organization
    if not exists (
      select 1 from public.org_members om
      where om.org_id = p_org_id
        and om.user_id = p_user_id
    ) then
      raise exception 'User is not a member of the target organization';
    end if;

    -- Execute the update (since we bypass RLS with SECURITY BYPASS, we can modify directly)
    -- Note: The policies above prevent direct SQL access, so this function is the only way.
    update public.org_members
    set role = p_role
    where org_id = p_org_id
      and user_id = p_user_id;

    return p_role;
  end;
end;
$$;

