  -- Check if role is valid
  if p_role not in ('owner', 'admin', 'member') then
    raise exception 'Invalid role: must be owner, admin, or member';
  end if;

  -- Get caller's organization membership
  select om.role into v_caller_role
  from public.org_members om
  where om.user_id = auth.uid() and om.org_id = p_org_id;

  -- If caller is not a member of the org, raise error
  if v_caller_role is null then
    raise exception 'Caller is not a member of the organization';
  end if;

  -- Check if caller is owner or admin
  if v_caller_role not in ('owner', 'admin') then
    raise exception 'Only owners and admins can set member roles';
  end if;

  -- Check if target user is in the same organization
  if not exists (
    select 1 from public.org_members om
    where om.org_id = p_org_id and om.user_id = p_user_id
  ) then
    raise exception 'Target user is not a member of the organization';
  end if;

  -- Check if target user is an owner (cannot demote or change owner)
  if p_user_id in (
    select user_id from public.org_members om
    where om.org_id = p_org_id and om.role = 'owner'
  ) then
    raise exception 'Cannot change the role of an owner';
  end if;

  -- Check if target user is the caller (must target someone else)
  if p_user_id = auth.uid() then
    raise exception 'Cannot set your own role';
  end if;

  -- Update the role
  update public.org_members
  set role = p_role
  where org_id = p_org_id and user_id = p_user_id;

  return p_role;
end;
